// Type definitions for translations
type Language = 'it' | 'en';
type TranslationKey = keyof typeof translations.it;

interface User {
  id: string;
  _id?: string;
  email: string | null;
  firstName: string;
  lastName: string;
  userType: 'guest' | 'registered' | 'architect' | 'admin';
  isVerified: boolean;
  orderNumber?: string;
  phone?: string;
  bio?: string;
  language: string;
  settings: UserSettings;
  architect?: ArchitectInfo;
  createdAt?: Date;
  lastLogin?: Date;
}

interface ArchitectInfo {
  orderNumber: string;
  specialties: string[];
  cfpCredits: number;
  profileVisible: boolean;
  acceptMessages: boolean;
  isAvailable: boolean;
  bio?: string;
  services?: string[];
  location?: string;
}

interface UserSettings {
  notifications: boolean;
  emailNotifications: boolean;
  language: string;
  privacy?: {
    showEmail: boolean;
    showPhone: boolean;
    showProjects: boolean;
  };
}

interface AuthContextType {
  user: User | null;
  login: (email: string, password: string) => Promise<{ success: boolean; error?: string }>;
  register: (userData: any) => Promise<{ success: boolean; error?: string; message?: string }>;
  loginAsGuest: () => Promise<void>;
  logout: () => void;
  updateSettings: (settings: Partial<UserSettings>) => Promise<boolean>;
  activateArchitectProfile: (token: string, orderNumber: string) => Promise<{ success: boolean; error?: string }>;
  loading: boolean;
  t: (key: string) => string;
  changeLanguage: (lang: string) => void;
}

interface ArchitectProfile {
  _id: string;
  userId: string;
  orderNumber: string;
  firstName: string;
  lastName: string;
  specialties: string[];
  location: string;
  bio: string;
  profileVisible: boolean;
  acceptMessages: boolean;
  cfpCredits: number;
  projects: number;
  rating: number;
  isAvailable: boolean;
  services: string[];
  portfolio: Portfolio[];
  certifications: string[];
  email?: string;
  phone?: string;
}

interface Portfolio {
  title: string;
  year: number;
  type: string;
  image: string;
  description?: string;
}

interface Course {
  id: string;
  title: string;
  description: string;
  date: Date;
  cfpCredits: number;
  price: number;
  seatsAvailable: number;
  totalSeats: number;
  instructor: string;
  location: string;
  online: boolean;
  enrolled?: boolean;
}

interface Message {
  id: string;
  from: string;
  fromId?: string;
  to?: string;
  toId?: string;
  subject: string;
  message: string;
  preview?: string;
  date: Date;
  unread: boolean;
  type: 'sent' | 'received';
}

interface News {
  id: string;
  title: string;
  excerpt: string;
  content: string;
  date: Date;
  category: string;
  author: string;
  image?: string;
  important: boolean;
}

