const LogoIcon: React.FC<{ size?: 'small' | 'medium' | 'large' }> = ({ size = 'medium' }) => {
  const sizes = {
    small: 40,
    medium: 60,
    large: 80
  };
  
  const currentSize = sizes[size];
  
  return (
    <div className={`logo-icon logo-${size}`} style={{ width: currentSize, height: currentSize }}>
      <svg viewBox="0 0 100 100" xmlns="http://www.w3.org/2000/svg">
        <defs>
          <linearGradient id="logoGradient" x1="0%" y1="0%" x2="100%" y2="100%">
            <stop offset="0%" stopColor="#2563eb" />
            <stop offset="100%" stopColor="#1d4ed8" />
          </linearGradient>
        </defs>
        <rect x="15" y="25" width="25" height="50" fill="url(#logoGradient)" rx="2" />
        <polygon points="15,25 27.5,10 40,25" fill="url(#logoGradient)" />
        <polygon points="45,35 45,75 75,55" fill="url(#logoGradient)" />
        <path d="M50 40 L60 60 L55 60 L52 55 L48 55 L45 60 L40 60 Z M49 50 L51 50 L50 48 Z" 
              fill="white" opacity="0.9" />
      </svg>
    </div>
  );
};

// =====================================
// AUTH CONTEXT PROVIDER COMPLETO
// =====================================

const AuthContext = createContext<AuthContextType | null>(null);

export const AuthProvider: React.FC<{ children: React.ReactNode }> = ({ children }) => {
  const [user, setUser] = useState<User | null>(null);
  const [loading, setLoading] = useState(false);
  const [currentLanguage, setCurrentLanguage] = useState<Language>(() => {
  // Forza sempre italiano
  localStorage.setItem('language', 'it');
  return 'it';
});

  // Initialize from localStorage
  useEffect(() => {
    const token = localStorage.getItem('token');
    const savedUser = localStorage.getItem('user');
    const savedLang = localStorage.getItem('language');
    
    if (savedLang) {
      setCurrentLanguage(savedLang as Language);
    }
    
    if (token && savedUser) {
      try {
        const userData = JSON.parse(savedUser);
        setUser(userData);
        // console.log('✅ User restored from localStorage:', userData.email);
      } catch (error) {
        console.error('Error parsing saved user:', error);
        localStorage.removeItem('token');
        localStorage.removeItem('user');
      }
    }
  }, []);

  const t = useCallback((key: string): string => {
    const lang = currentLanguage as Language;
    const translations_lang = translations[lang];
    const translation = translations_lang[key as keyof typeof translations_lang];
    return translation || key;
  }, [currentLanguage]);

  const changeLanguage = useCallback((lang: string) => {
    setCurrentLanguage(lang as Language);
    localStorage.setItem('language', lang);
    
    // Update user language if logged in
    if (user) {
      const updatedUser = { ...user, language: lang };
      setUser(updatedUser);
      localStorage.setItem('user', JSON.stringify(updatedUser));
      
      // Update on server
      authService.updateSettings(user.id, { language: lang } as any)
        .catch(err => console.error('Error updating language:', err));
    }
  }, [user]);

  const login = async (email: string, password: string) => {
    try {
      setLoading(true);
      const response = await authService.login({ email, password });
      
      if (response.success && response.user) {
        setUser(response.user as unknown as User);
        // console.log('✅ Login successful:', response.user.email);
        return { success: true };
      }
      
      return { success: false, error: t('loginError') };
    } catch (error: any) {
      const errorMessage = error.message || t('loginError');
      console.error('Login error:', errorMessage);
      return { success: false, error: errorMessage };
    } finally {
      setLoading(false);
    }
  };

  const register = async (userData: any) => {
    try {
      setLoading(true);
      const response = await authService.register(userData);
      // Auto-login dopo registrazione: aggiorna stato utente
      if (response.success && response.user) {
        setUser(response.user as unknown as User);
      }
      return { success: true, message: response.message };
    } catch (error: any) {
      return { success: false, error: error.message || t('registrationError') };
    } finally {
      setLoading(false);
    }
  };

  const loginAsGuest = async () => {
    try {
      setLoading(true);
      const response = await authService.guestAccess();
      
      if (response.success && response.user) {
        setUser(response.user as unknown as User);
        // console.log('✅ Guest access granted');
      }
    } catch (error) {
      console.error('Guest login error:', error);
    } finally {
      setLoading(false);
    }
  };

 const logout = () => {
    authService.logout();
    setUser(null);
    // console.log('👋 User logged out');
  };

  const updateSettings = async (settings: Partial<UserSettings>) => {
    if (!user) return false;
    
    try {
      const response = await authService.updateSettings(user._id || user.id, settings);
      
      if (response.success && response.settings) {
        const updatedUser = {
          ...user,
          settings: response.settings as UserSettings,
          language: settings.language || user.language
        };
        
        setUser(updatedUser);
        localStorage.setItem('user', JSON.stringify(updatedUser));
        
        if (settings.language) {
          setCurrentLanguage(settings.language as Language);
          localStorage.setItem('language', settings.language);
        }
        
        return true;
      }
      return false;
    } catch (error) {
      console.error('Settings update error:', error);
      return false;
    }
  };

  const activateArchitectProfile = async (token: string, orderNumber: string) => {
    try {
      setLoading(true);
      // console.log('🔍 ATTIVAZIONE - Token:', token);
      // console.log('🔍 ATTIVAZIONE - Numero:', orderNumber);
      const response = await authService.activateArchitect({
        activationToken: token,
        orderNumber: orderNumber
      });
      
      if (response.success && response.user) {
        const updatedUser: User = {
          id: response.user._id || response.user.id || '',
          email: response.user.email,
          firstName: response.user.firstName,
          lastName: response.user.lastName,
          userType: 'architect',
          isVerified: true,
          orderNumber: response.user.orderNumber,
          phone: user?.phone || '',
          language: user?.language || 'it',
          settings: user?.settings || {
            notifications: true,
            emailNotifications: true,
            
            language: 'it'
          },
          architect: {
            orderNumber: response.user.orderNumber || orderNumber,
            specialties: [],
            cfpCredits: 0,
            profileVisible: true,
            acceptMessages: true,
            isAvailable: true
          }
        };
        
        setUser(updatedUser);
        localStorage.setItem('user', JSON.stringify(updatedUser));
        // console.log('✅ Profilo architetto attivato e UI sincronizzata:', updatedUser);
      }
      
      return { success: true };
    } catch (error: any) {
      return { 
        success: false, 
        error: error.message || t('errorDuringActivation')
      };
    } finally {
      setLoading(false);
    }
  };

  const contextValue = useMemo(() => ({
    user,
    login,
    register,
    loginAsGuest,
    logout,
    updateSettings,
    activateArchitectProfile,
    loading,
    t,
    changeLanguage
  }), [user, loading, t, changeLanguage]);

  return (
    <AuthContext.Provider value={contextValue}>
      {children}
    </AuthContext.Provider>
  );
};

const useAuth = () => {
  const context = useContext(AuthContext);
  if (!context) {
    throw new Error('useAuth must be used within an AuthProvider');
  }
  return context;
};

