// =====================================
// ONBOARDING SCREEN COMPONENT
// =====================================

const OnboardingScreen: React.FC<{ onComplete: () => void }> = ({ onComplete }) => {
  const [currentSlide, setCurrentSlide] = useState(0);
  const { t } = useAuth();
  
  const slides = [
    {
      icon: '🏛️',
      title: t('welcomeToApp'),
      description: t('officialApp')
    },
    {
      icon: '🔍',
      title: t('searchArchitects'),
      description: 'Trova professionisti qualificati nella tua zona'
    },
    {
      icon: '📚',
      title: 'Corsi e Formazione',
      description: 'Resta aggiornato con i corsi CFP'
    },
    {
      icon: '💬',
      title: 'Connettiti',
      description: 'Messaggia direttamente con i professionisti'
    }
  ];
  
  const nextSlide = () => {
    if (currentSlide < slides.length - 1) {
      setCurrentSlide(currentSlide + 1);
    } else {
      onComplete();
    }
  };
  
  const skipOnboarding = () => {
    onComplete();
  };
  
  return (
    <div className="onboarding-screen">
      <button className="skip-button" onClick={skipOnboarding}>
        Salta
      </button>
      
      <div className="onboarding-content">
        <div className="onboarding-slide">
          <div className="slide-icon">{slides[currentSlide].icon}</div>
          <h2>{slides[currentSlide].title}</h2>
          <p>{slides[currentSlide].description}</p>
        </div>
        
        <div className="slide-indicators">
          {slides.map((_, index) => (
            <div
              key={index}
              className={`indicator ${index === currentSlide ? 'active' : ''}`}
              onClick={() => setCurrentSlide(index)}
            />
          ))}
        </div>
        
        <button className="next-button" onClick={nextSlide}>
          {currentSlide === slides.length - 1 ? t('start') : t('next')}
        </button>
      </div>
    </div>
  );
};

// =====================================
// AUTH SCREEN COMPONENT COMPLETO
// =====================================

const AuthScreen: React.FC<{ showToast: (message: string, type?: string) => void }> = ({
  showToast
}) => {
  const { login, register, loginAsGuest, logout, loading, t, changeLanguage } = useAuth();

  const [activeTab, setActiveTab] = useState<'login' | 'register'>('login');
  const [showForgotPassword, setShowForgotPassword] = useState(false);
  const [forgotEmail, setForgotEmail] = useState('');
  const [forgotLoading, setForgotLoading] = useState(false);
  const [currentLanguage, setCurrentLanguage] = useState<Language>(() => {
    const saved = localStorage.getItem('language');
    return (saved as Language) || 'it';
  });
  const [formData, setFormData] = useState({
    email: '',
    password: '',
    confirmPassword: '',
    firstName: '',
    lastName: '',
    phone: '',
    userType: 'registered' as 'registered' | 'architect',
    orderNumber: '',
    activationToken: '',
    acceptTerms: false,
    acceptPrivacy: false
  });
  const [errors, setErrors] = useState<any>({});
  const [showPassword, setShowPassword] = useState(false);

  const handleLanguageChange = (lang: Language) => {
    setCurrentLanguage(lang);
    changeLanguage(lang);
  };

  const validateForm = () => {
    const newErrors: any = {};
    
    // Email validation
    const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
    if (!formData.email) {
      newErrors.email = t('requiredField');
    } else if (!emailRegex.test(formData.email)) {
      newErrors.email = t('invalidEmail');
    }
    
    // Password validation
    if (!formData.password) {
      newErrors.password = t('requiredField');
    } else if (activeTab === 'register') {
      if (formData.password.length < 6) {
        newErrors.password = t('passwordTooShort');
      }
      if (formData.password !== formData.confirmPassword) {
        newErrors.confirmPassword = t('passwordsDoNotMatch');
      }
    }
    
    if (activeTab === 'register') {
      if (!formData.firstName) newErrors.firstName = t('requiredField');
      if (!formData.lastName) newErrors.lastName = t('requiredField');
      if (!formData.acceptTerms) newErrors.acceptTerms = t('mustAcceptTerms');
      if (!formData.acceptPrivacy) newErrors.acceptPrivacy = t('mustAcceptPrivacy');
      
      if (formData.userType === 'architect') {
        if (!formData.orderNumber) newErrors.orderNumber = t('orderNumberRequired');
        if (!formData.activationToken) newErrors.activationToken = t('tokenRequired');
      }
    }
    
    setErrors(newErrors);
    return Object.keys(newErrors).length === 0;
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    
    if (!validateForm()) return;
    
    if (activeTab === 'login') {
      const result = await login(formData.email, formData.password);
      if (result.success) {
        showToast(t('loginSuccess'), 'success');
      } else {
        showToast(result.error || t('loginError'), 'error');
      }
    } else {
      const registrationData = {
        ...formData,
        activationToken: formData.userType === 'architect' ? formData.activationToken : undefined
      };
      
      const result = await register(registrationData);
      if (result.success) {
        showToast(result.message || t('registrationSuccess'), 'success');
        setActiveTab('login');
        // Reset form but keep email
        setFormData({ 
          ...formData, 
          password: '', 
          confirmPassword: '',
          firstName: '', 
          lastName: '', 
          phone: '', 
          orderNumber: '',
          activationToken: '', 
          acceptTerms: false,
          acceptPrivacy: false 
        });
      } else {
        showToast(result.error || t('registrationError'), 'error');
      }
    }
  };

  const handleGuestAccess = async () => {
    await loginAsGuest();
    showToast('Accesso ospite - Funzionalità limitate', 'info');
  };

  const handleInputChange = (field: string, value: any) => {
    setFormData(prev => ({ ...prev, [field]: value }));
    // Clear error when user starts typing
    if (errors[field]) {
      setErrors((prev: any) => ({ ...prev, [field]: undefined }));
    }
  };

  const handleForgotPassword = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!forgotEmail) {
      showToast(t('invalidEmail'), 'error');
      return;
    }
    const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
    if (!emailRegex.test(forgotEmail)) {
      showToast(t('invalidEmail'), 'error');
      return;
    }
    setForgotLoading(true);
    try {
      const response = await fetch(`${API_BASE}/auth/forgot-password`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ email: forgotEmail })
      });
      if (!response.ok && response.status >= 500) {
        // Errore server — mostra errore generico
        throw new Error('Server error');
      }
      // Per sicurezza mostriamo sempre successo (non rivela se email esiste)
      showToast(
        currentLanguage === 'it'
          ? 'Se questa email è registrata, riceverai le istruzioni per reimpostare la password.'
          : 'If this email is registered, you will receive password reset instructions.',
        'success'
      );
      setShowForgotPassword(false);
      setForgotEmail('');
    } catch (error) {
      showToast(
        currentLanguage === 'it' ? 'Errore di connessione. Riprova.' : 'Connection error. Please try again.',
        'error'
      );
    } finally {
      setForgotLoading(false);
    }
  };

  return (
    <div className="auth-screen">
      <div className="auth-container">
        <div className="auth-header">
          <LogoIcon size="large" />
          <h1>{t('orderArchitects')}</h1>
          <p>Provincia di Caltanissetta</p>
          
          <div className="language-selector">
            <button 
              onClick={() => handleLanguageChange('it')}
              className={`lang-button ${currentLanguage === 'it' ? 'active' : ''}`}
            >
              🇮🇹 IT
            </button>
            <button 
              onClick={() => handleLanguageChange('en')}
              className={`lang-button ${currentLanguage === 'en' ? 'active' : ''}`}
            >
              🇬🇧 EN
            </button>
          </div>
        </div>

        <div className="auth-tabs">
          <button 
            className={`auth-tab ${activeTab === 'login' ? 'active' : ''}`}
            onClick={() => setActiveTab('login')}
          >
            {t('login')}
          </button>
          <button 
            className={`auth-tab ${activeTab === 'register' ? 'active' : ''}`}
            onClick={() => setActiveTab('register')}
          >
            {t('register')}
          </button>
        </div>

        <form onSubmit={handleSubmit} className="auth-form">
          {activeTab === 'register' && (
            <>
              <div className="form-row">
                <div className="form-group">
                  <input
                    type="text"
                    placeholder={t('firstName')}
                    value={formData.firstName}
                    onChange={(e) => handleInputChange('firstName', e.target.value)}
                    className={errors.firstName ? 'error' : ''}
                  />
                  {errors.firstName && <span className="error-message">{errors.firstName}</span>}
                </div>
                <div className="form-group">
                  <input
                    type="text"
                    placeholder={t('lastName')}
                    value={formData.lastName}
                    onChange={(e) => handleInputChange('lastName', e.target.value)}
                    className={errors.lastName ? 'error' : ''}
                  />
                  {errors.lastName && <span className="error-message">{errors.lastName}</span>}
                </div>
              </div>
              
              <div className="form-group">
                <input
                  type="tel"
                  placeholder={`${t('phone')} (opzionale)`}
                  value={formData.phone}
                  onChange={(e) => handleInputChange('phone', e.target.value)}
                />
              </div>
              
              <div className="form-group">
                <select 
                  className="form-select"
                  value={formData.userType}
                  onChange={(e) => handleInputChange('userType', e.target.value)}
                >
                  <option value="registered">{t('registered')}</option>
                  <option value="architect">{t('architect')} (richiede token)</option>
                </select>
              </div>
              
              {formData.userType === 'architect' && (
                <>
                  <div className="form-group">
                    <input
                      type="text"
                      placeholder={t('orderNumber')}
                      value={formData.orderNumber}
                      onChange={(e) => handleInputChange('orderNumber', e.target.value)}
                      className={errors.orderNumber ? 'error' : ''}
                    />
                    {errors.orderNumber && <span className="error-message">{errors.orderNumber}</span>}
                  </div>
                  
                  <div className="form-group">
                    <input
                      type="text"
                      placeholder={t('activationToken')}
                      value={formData.activationToken}
                      onChange={(e) => handleInputChange('activationToken', e.target.value)}
                      className={errors.activationToken ? 'error' : ''}
                    />
                    {errors.activationToken && <span className="error-message">{errors.activationToken}</span>}
                    <small className="form-help">
                      Il token ti è stato fornito dalla segreteria via PEC
                    </small>
                  </div>
                </>
              )}
            </>
          )}
          
          <div className="form-group">
            <input
              type="email"
              placeholder={t('email')}
              value={formData.email}
              onChange={(e) => handleInputChange('email', e.target.value)}
              className={errors.email ? 'error' : ''}
              autoComplete="email"
            />
            {errors.email && <span className="error-message">{errors.email}</span>}
          </div>
          
          <div className="form-group password-group">
            <input
              type={showPassword ? 'text' : 'password'}
              placeholder={t('password')}
              value={formData.password}
              onChange={(e) => handleInputChange('password', e.target.value)}
              className={errors.password ? 'error' : ''}
              autoComplete={activeTab === 'login' ? 'current-password' : 'new-password'}
            />
            <button 
              type="button" 
              className="password-toggle"
              onClick={() => setShowPassword(!showPassword)}
            >
              {showPassword ? '👁️' : '👁️‍🗨️'}
            </button>
            {errors.password && <span className="error-message">{errors.password}</span>}
          </div>

          {activeTab === 'register' && (
            <>
              <div className="form-group password-group">
                <input
                  type={showPassword ? 'text' : 'password'}
                  placeholder={t('confirmPassword')}
                  value={formData.confirmPassword}
                  onChange={(e) => handleInputChange('confirmPassword', e.target.value)}
                  className={errors.confirmPassword ? 'error' : ''}
                  autoComplete="new-password"
                />
                {errors.confirmPassword && <span className="error-message">{errors.confirmPassword}</span>}
              </div>

              <div className="form-checkbox">
                <label>
                  <input
                    type="checkbox"
                    checked={formData.acceptTerms}
                    onChange={(e) => handleInputChange('acceptTerms', e.target.checked)}
                  />
                 {t('acceptTerms')} <a href="#terms" target="_blank">{t('termsOfService')}</a>
                </label>
                {errors.acceptTerms && <span className="error-message">{errors.acceptTerms}</span>}
              </div>

              <div className="form-checkbox">
                <label>
                  <input
                    type="checkbox"
                    checked={formData.acceptPrivacy}
                    onChange={(e) => handleInputChange('acceptPrivacy', e.target.checked)}
                  />
                  Accetto la <a href="#privacy" target="_blank">Privacy Policy</a>
                </label>
                {errors.acceptPrivacy && <span className="error-message">{errors.acceptPrivacy}</span>}
              </div>
            </>
          )}

          <button type="submit" disabled={loading} className="submit-button">
            {loading ? <LoadingSpinner /> : (activeTab === 'login' ? t('login') : t('register'))}
          </button>
        </form>

        {activeTab === 'login' && (
          <>
            <div className="divider">oppure</div>
            <button onClick={handleGuestAccess} className="guest-button">
              {t('guestAccess')}
            </button>
            <button
              type="button"
              className="forgot-link"
              onClick={() => { setShowForgotPassword(true); setForgotEmail(''); }}
              style={{ background: 'none', border: 'none', cursor: 'pointer', padding: 0 }}
            >
              {t('forgotPassword')}
            </button>
          </>
        )}

        {showForgotPassword && (
          <div className="forgot-password-modal" style={{
            position: 'fixed', inset: 0, background: 'rgba(0,0,0,0.5)',
            display: 'flex', alignItems: 'center', justifyContent: 'center', zIndex: 1000
          }}>
            <div className="forgot-password-box" style={{
              background: '#fff', borderRadius: '12px', padding: '32px',
              width: '100%', maxWidth: '400px', boxShadow: '0 8px 32px rgba(0,0,0,0.15)'
            }}>
              <h3 style={{ marginBottom: '8px', color: '#1a1a2e' }}>
                {currentLanguage === 'it' ? '🔑 Recupera Password' : '🔑 Reset Password'}
              </h3>
              <p style={{ color: '#666', marginBottom: '20px', fontSize: '14px' }}>
                {currentLanguage === 'it'
                  ? 'Inserisci la tua email. Ti invieremo le istruzioni per reimpostare la password.'
                  : 'Enter your email. We will send you instructions to reset your password.'}
              </p>
              <form onSubmit={handleForgotPassword}>
                <div className="form-group" style={{ marginBottom: '16px' }}>
                  <label style={{ display: 'block', marginBottom: '6px', fontWeight: 500 }}>
                    {currentLanguage === 'it' ? 'Indirizzo Email' : 'Email Address'}
                  </label>
                  <input
                    type="email"
                    value={forgotEmail}
                    onChange={e => setForgotEmail(e.target.value)}
                    placeholder={currentLanguage === 'it' ? 'La tua email' : 'Your email'}
                    style={{
                      width: '100%', padding: '10px 12px', borderRadius: '8px',
                      border: '1px solid #ddd', fontSize: '14px', boxSizing: 'border-box'
                    }}
                    required
                    autoFocus
                  />
                </div>
                <div style={{ display: 'flex', gap: '10px' }}>
                  <button
                    type="button"
                    onClick={() => { setShowForgotPassword(false); setForgotEmail(''); }}
                    style={{
                      flex: 1, padding: '10px', borderRadius: '8px', border: '1px solid #ddd',
                      background: '#f5f5f5', cursor: 'pointer', fontSize: '14px'
                    }}
                  >
                    {currentLanguage === 'it' ? 'Annulla' : 'Cancel'}
                  </button>
                  <button
                    type="submit"
                    disabled={forgotLoading}
                    style={{
                      flex: 1, padding: '10px', borderRadius: '8px', border: 'none',
                      background: forgotLoading ? '#aaa' : '#6366f1', color: '#fff',
                      cursor: forgotLoading ? 'not-allowed' : 'pointer', fontSize: '14px', fontWeight: 600
                    }}
                  >
                    {forgotLoading
                      ? (currentLanguage === 'it' ? 'Invio...' : 'Sending...')
                      : (currentLanguage === 'it' ? 'Invia Link' : 'Send Link')}
                  </button>
                </div>
              </form>
            </div>
          </div>
        )}

        <div className="auth-switch">
  {activeTab === 'login' ? (
<p>{t('notRegistered')} <button onClick={() => setActiveTab('register')} className="link-button">{t('register')}</button></p>  ) : (
    <p>{t('alreadyRegistered')} <button onClick={() => setActiveTab('login')} className="link-button">{t('login')}</button></p>
  )}
</div>

        <div className="test-accounts">
          <h4>🧪 {t('testAccountsAvailable')}</h4>
          <div className="test-account-list">
            <div className="test-account">
              <strong>🔑 Amministratore:</strong>
              <p>admin@ordinearchitetti.cl.it | Admin2024!</p>
            </div>
            <div className="test-account">
              <strong>Architetto Verificato:</strong>
              <p>laura.bianchi@test.it | password123</p>
            </div>
            <div className="test-account">
              <strong>Architetto Verificato:</strong>
              <p>giuseppe.verdi@test.it | password123</p>
            </div>
            <div className="test-account token-info">
              <strong>🎫 {t('tokenAvailable')}:</strong>
              <p>ARCH-TOKEN-2025-001</p>
              <p>Numero Ordine: 2001</p>
            </div>
          </div>
        </div>
      </div>
    </div>
  );
};

// =====================================
// RESET PASSWORD SCREEN
// =====================================

const ResetPasswordScreen: React.FC<{
  token: string;
  showToast: (message: string, type?: string) => void;
  onDone: () => void;
}> = ({ token, showToast, onDone }) => {
  const [newPassword, setNewPassword] = useState('');
  const [confirmPassword, setConfirmPassword] = useState('');
  const [loading, setLoading] = useState(false);
  const [showPwd, setShowPwd] = useState(false);

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (newPassword.length < 6) {
      showToast('La password deve essere almeno 6 caratteri', 'error');
      return;
    }
    if (newPassword !== confirmPassword) {
      showToast('Le password non coincidono', 'error');
      return;
    }
    setLoading(true);
    try {
      const res = await fetch(`${API_BASE}/auth/reset-password`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ token, newPassword }),
      });
      const data = await res.json();
      if (!res.ok) throw new Error(data.message || 'Errore durante il reset');
      showToast('Password reimpostata con successo! Ora puoi accedere.', 'success');
      window.history.replaceState({}, document.title, window.location.pathname);
      onDone();
    } catch (err: any) {
      showToast(err.message || 'Errore durante il reset della password', 'error');
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="auth-screen">
      <div className="auth-container">
        <div className="auth-logo">
          <div className="logo-icon">🏛️</div>
          <h1>Ordine Architetti</h1>
          <p>Provincia di Caltanissetta</p>
        </div>
        <div className="auth-card">
          <h2 style={{ textAlign: 'center', marginBottom: '8px' }}>🔑 Nuova Password</h2>
          <p style={{ textAlign: 'center', color: '#666', marginBottom: '24px', fontSize: '14px' }}>
            Scegli una nuova password per il tuo account.
          </p>
          <form onSubmit={handleSubmit} className="auth-form">
            <div className="form-group">
              <div className="input-wrapper">
                <input
                  type={showPwd ? 'text' : 'password'}
                  placeholder="Nuova password"
                  value={newPassword}
                  onChange={e => setNewPassword(e.target.value)}
                  className="form-input"
                  required
                />
                <button type="button" className="toggle-password" onClick={() => setShowPwd(p => !p)}>
                  {showPwd ? '🙈' : '👁️'}
                </button>
              </div>
            </div>
            <div className="form-group">
              <input
                type={showPwd ? 'text' : 'password'}
                placeholder="Conferma nuova password"
                value={confirmPassword}
                onChange={e => setConfirmPassword(e.target.value)}
                className="form-input"
                required
              />
            </div>
            <button type="submit" disabled={loading} className="submit-button">
              {loading ? 'Reimpostazione...' : 'Reimposta Password'}
            </button>
          </form>
        </div>
      </div>
    </div>
  );
};

// =====================================
// APP HEADER COMPONENT
// =====================================

const AppHeader: React.FC<{ user: User | null; onLogout: () => void }> = ({ user, onLogout }) => {
  const { t } = useAuth();
  const [showNotifications, setShowNotifications] = useState(false);
  const [showUserMenu, setShowUserMenu] = useState(false);
  const [notifications, setNotifications] = useState<any[]>([]);
  const [notifLoading, setNotifLoading] = useState(false);

  // Carica notifiche dall'API
  const fetchNotifications = async () => {
    if (!user || user.userType === 'guest') return;
    setNotifLoading(true);
    try {
      const res = await fetch(`${API_BASE}/notifications?limit=20`, {
        headers: { Authorization: `Bearer ${localStorage.getItem('token') || ''}` }
      });
      if (res.ok) {
        const data = await res.json();
        if (data.success && Array.isArray(data.data)) {
          setNotifications(data.data);
        }
      }
    } catch {
      // Silenzioso — le notifiche sono opzionali
    } finally {
      setNotifLoading(false);
    }
  };

  useEffect(() => {
    fetchNotifications();
  }, [user]);

  const unreadCount = notifications.filter((n: any) => !n.read).length;

  const handleMarkAsRead = async (notif: any) => {
    if (notif.read) return;
    // Ottimistic update
    setNotifications(prev => prev.map(n => n._id === notif._id ? { ...n, read: true } : n));
    try {
      await fetch(`${API_BASE}/notifications/${notif._id}/read`, {
        method: 'PATCH',
        headers: { Authorization: `Bearer ${localStorage.getItem('token') || ''}` }
      });
    } catch { /* rollback se serve */ }
  };

  const handleMarkAllAsRead = async () => {
    setNotifications(prev => prev.map(n => ({ ...n, read: true })));
    try {
      await fetch(`${API_BASE}/notifications/read-all`, {
        method: 'PATCH',
        headers: { Authorization: `Bearer ${localStorage.getItem('token') || ''}` }
      });
    } catch { /* silenzioso */ }
  };

  const handleDeleteNotification = async (id: string, e: React.MouseEvent) => {
    e.stopPropagation();
    setNotifications(prev => prev.filter(n => n._id !== id));
    try {
      await fetch(`${API_BASE}/notifications/${id}`, {
        method: 'DELETE',
        headers: { Authorization: `Bearer ${localStorage.getItem('token') || ''}` }
      });
    } catch { /* silenzioso */ }
  };

  const notifIcon = (type: string) => {
    if (type === 'course') return '📚';
    if (type === 'message') return '💬';
    if (type === 'news') return '📰';
    return '🔔';
  };

  const formatNotifTime = (createdAt: string) => {
    const diff = Date.now() - new Date(createdAt).getTime();
    const min = Math.floor(diff / 60000);
    if (min < 1) return 'Adesso';
    if (min < 60) return `${min} min fa`;
    const h = Math.floor(min / 60);
    if (h < 24) return `${h}h fa`;
    return `${Math.floor(h / 24)}g fa`;
  };

  return (
    <header className="app-header">
      <div className="header-left">
        <LogoIcon size="small" />
        <div className="header-title">
          <h1>{t('architects')}</h1>
          <p>Prov. Caltanissetta</p>
        </div>
      </div>

      <div className="header-right">
        {user?.userType !== 'guest' && (
          <button
            className="notification-button"
            onClick={() => { setShowNotifications(!showNotifications); if (!showNotifications) fetchNotifications(); }}
          >
            🔔
            {unreadCount > 0 && (
              <span className="notification-badge">{unreadCount > 99 ? '99+' : unreadCount}</span>
            )}
          </button>
        )}

        <button
          className="user-menu-button"
          onClick={() => setShowUserMenu(!showUserMenu)}
        >
          <div className="user-avatar-small">
            {user?.firstName?.[0]}{user?.lastName?.[0]}
          </div>
        </button>
      </div>

      {showNotifications && (
        <div className="notifications-panel">
          <div className="notifications-header">
            <h3>{t('notifications')}</h3>
            <div className="notification-actions">
              {unreadCount > 0 && (
                <button onClick={handleMarkAllAsRead} className="clear-all">
                  Segna tutte lette
                </button>
              )}
              <button onClick={() => setShowNotifications(false)}>×</button>
            </div>
          </div>
          <div className="notifications-list">
            {notifLoading ? (
              <p className="no-notifications">Caricamento...</p>
            ) : notifications.length === 0 ? (
              <p className="no-notifications">{t('noNotifications')}</p>
            ) : (
              notifications.map((notif: any) => (
                <div
                  key={notif._id}
                  className={`notification-item ${!notif.read ? 'unread' : ''}`}
                  onClick={() => handleMarkAsRead(notif)}
                >
                  <div className="notification-icon">{notifIcon(notif.type)}</div>
                  <div className="notification-content">
                    <h4>{notif.title}</h4>
                    <p>{notif.message}</p>
                    <span className="notification-time">{formatNotifTime(notif.createdAt)}</span>
                  </div>
                  <button
                    className="notif-delete"
                    onClick={(e) => handleDeleteNotification(notif._id, e)}
                    title="Elimina"
                    style={{ background: 'none', border: 'none', cursor: 'pointer', color: '#aaa', fontSize: '16px', padding: '4px' }}
                  >
                    ×
                  </button>
                </div>
              ))
            )}
          </div>
        </div>
      )}

      {showUserMenu && (
        <div className="user-menu-dropdown">
          <div className="user-menu-header">
            <div className="user-avatar-large">
              {user?.firstName?.[0]}{user?.lastName?.[0]}
            </div>
            <div className="user-info">
              <h4>{user?.firstName} {user?.lastName}</h4>
              <p>{user?.email}</p>
            </div>
          </div>
          <div className="user-menu-items">
            <button onClick={() => setShowUserMenu(false)}>
              <span>👤</span> Profilo
            </button>
            <button onClick={() => setShowUserMenu(false)}>
              <span>⚙️</span> Impostazioni
            </button>
            <button onClick={() => setShowUserMenu(false)}>
              <span>❓</span> Aiuto
            </button>
            <div className="menu-divider"></div>
            <button onClick={onLogout} className="logout-button">
              <span>🚪</span> {t('logout')}
            </button>
          </div>
        </div>
      )}
    </header>
  );
};

// =====================================
// BOTTOM NAV COMPONENT
// =====================================

const BottomNav: React.FC<{
  currentPage: string;
  setCurrentPage: (page: string) => void;
  userType: string;
  unreadMessages?: number;
}> = ({ currentPage, setCurrentPage, userType, unreadMessages = 0 }) => {
  const { t } = useAuth();

  const navItems = [
    { id: 'home', icon: '🏠', label: t('home'), badge: 0 },
    { id: 'search', icon: '🔍', label: t('search'), badge: 0 },
    ...(userType !== 'guest' ? [{ id: 'chat', icon: '💬', label: t('messages'), badge: unreadMessages }] : []),
    { id: 'courses', icon: '📚', label: t('courses'), badge: 0 },
    { id: 'profile', icon: '👤', label: t('profile'), badge: 0 }
  ];

  return (
    <nav className="bottom-nav">
      {navItems.map(item => (
        <button
          key={item.id}
          className={`nav-item ${currentPage === item.id ? 'active' : ''}`}
          onClick={() => setCurrentPage(item.id)}
        >
          <span className="nav-icon" style={{ position: 'relative', display: 'inline-block' }}>
            {item.icon}
            {item.badge > 0 && (
              <span style={{
                position: 'absolute', top: '-6px', right: '-8px',
                background: '#ef4444', color: '#fff', borderRadius: '50%',
                fontSize: '10px', fontWeight: 700, minWidth: '16px', height: '16px',
                display: 'flex', alignItems: 'center', justifyContent: 'center',
                lineHeight: 1, padding: '0 2px'
              }}>
                {item.badge > 99 ? '99+' : item.badge}
              </span>
            )}
          </span>
          <span className="nav-label">{item.label}</span>
        </button>
      ))}
    </nav>
  );
};

