const ChatPage: React.FC<{ 
  showToast: (message: string, type?: string) => void;
  selectedArchitect?: any;
}> = ({ 
  showToast,
  selectedArchitect 
}) => {
  const { user, t } = useAuth();
  const [conversations, setConversations] = useState<any[]>([]);
  const [selectedConversation, setSelectedConversation] = useState<any>(null);
  const [messages, setMessages] = useState<Message[]>([]);
  const [newMessage, setNewMessage] = useState('');
  const [loading, setLoading] = useState(false);
  const messagesEndRef = useRef<HTMLDivElement>(null);
  // 👇 AGGIUNGI QUESTO BLOCCO QUI
  // Apri automaticamente conversazione se richiesta
  useEffect(() => {
    const openConvId = localStorage.getItem('openConversationId');
    
    if (openConvId && conversations.length > 0) {
      // Trova la conversazione con quell'ID
      const conv = conversations.find(c => c.id === openConvId);
      
      if (conv) {
        // Aprila!
        selectConversation(conv);
        // Pulisci localStorage
        localStorage.removeItem('openConversationId');
      }
    }
  }, [conversations]); // Si attiva quando le conversazioni vengono caricate

  useEffect(() => {
    // Carica conversazioni per tutti gli utenti autenticati (non guest)
    if (user && user.userType !== 'guest') {
      fetchConversations();
    }
  }, [user]);

  useEffect(() => {
    scrollToBottom();
  }, [messages]);

  const scrollToBottom = () => {
    messagesEndRef.current?.scrollIntoView({ behavior: 'smooth' });
  };

  // Controllo accesso: solo utenti autenticati (no guest)
  if (!user) {
    return (
      <div className="chat-page">
        <div className="empty-state">
          <h3>⚠️ Effettua l'accesso</h3>
          <p>Devi effettuare l'accesso per utilizzare la messaggistica.</p>
        </div>
      </div>
    );
  }

  if (user.userType === 'guest') {
    return (
      <div className="chat-page">
        <div className="empty-state">
          <h3>🔒 Funzionalità Riservata</h3>
          <p>Registrati o accedi con il tuo account per usare la messaggistica.</p>
        </div>
      </div>
    );
  }
  const fetchConversations = async () => {
    try {
      setLoading(true);
      const response = await messagesService.getConversations();
      
      if (response.success && response.conversations) {
        // Mappa le conversazioni dal backend al formato locale
        const mappedConversations = response.conversations.map((conv: any) => ({
          id: conv._id,
          participant: conv.participant ? `${conv.participant.firstName} ${conv.participant.lastName}` : 'Utente',
          participantType: conv.participant?.userType || 'registered',
          lastMessage: conv.lastMessage?.content || 'Nessun messaggio',
          lastMessageTime: conv.lastMessage?.createdAt ? new Date(conv.lastMessage.createdAt) : new Date(conv.updatedAt),
          unread: conv.unreadCount || 0,
          avatar: conv.participant ? `${conv.participant.firstName?.[0] || ''}${conv.participant.lastName?.[0] || ''}` : '??'
        }));
        setConversations(mappedConversations);
      } else {
        // Fallback con dati mock se non ci sono conversazioni
        setConversations([]);
      }
    } catch (error) {
      console.error('Error fetching conversations:', error);
      showToast('Errore nel caricamento delle conversazioni', 'error');
    } finally {
      setLoading(false);
    }
  };

  const selectConversation = async (conversation: any) => {
    setSelectedConversation(conversation);
    
    // Marca come letti
    setConversations(prev => 
      prev.map(c => c.id === conversation.id ? { ...c, unread: 0 } : c)
    );
    
    try {
      // Carica messaggi REALI dal backend
      const response = await messagesService.getConversationMessages(conversation.id);
      // console.log('🔍 RISPOSTA BACKEND MESSAGGI:', response);
      
      if (response.success && response.messages) {
        const mappedMessages: Message[] = response.messages.map((msg: any) => ({
          id: msg._id,
          from: msg.sender?.firstName || 'Utente',
          to: msg.isOwn ? conversation.participant : user?.firstName || '',
          subject: '',
          message: msg.content,
          date: new Date(msg.createdAt),
          unread: !msg.readAt,
          type: msg.isOwn ? 'sent' : 'received'
        }));
        setMessages(mappedMessages);
      } else {
        // Conversazione nuova, nessun messaggio
        setMessages([]);
      }
    } catch (error) {
      console.error('Error loading messages:', error);
      showToast('Errore caricamento messaggi', 'error');
      setMessages([]);
    }
  };

  const sendMessage = async () => {
    if (!newMessage.trim() || !selectedConversation) return;
    
    try {
      const response = await messagesService.sendMessage(selectedConversation.id, newMessage.trim());
      
      if (response.success && response.message) {
        const msgData = response.message as any;
        const message: Message = {
          id: msgData._id || Date.now().toString(),
          from: user?.firstName || '',
          to: selectedConversation.participant,
          subject: t('messageBody'),
          message: msgData.content || newMessage,
          date: new Date(msgData.createdAt || Date.now()),
          unread: false,
          type: 'sent'
        };
        
        setMessages(prev => [...prev, message]);
        setNewMessage('');
        
        // Aggiorna ultima conversazione
        setConversations(prev => 
          prev.map(c => c.id === selectedConversation.id 
            ? { ...c, lastMessage: newMessage, lastMessageTime: new Date() }
            : c
          )
        );
        
        showToast(t('messageSent'), 'success');
      }
    } catch (error) {
      console.error('Error sending message:', error);
      showToast('Errore nell\'invio del messaggio', 'error');
    }
  };

  const formatTime = (date: Date) => {
    const now = new Date();
    const messageDate = new Date(date);
    const diff = now.getTime() - messageDate.getTime();
    const days = Math.floor(diff / (1000 * 60 * 60 * 24));
    
    if (days === 0) {
      return messageDate.toLocaleTimeString('it-IT', { hour: '2-digit', minute: '2-digit' });
    } else if (days === 1) {
      return 'Ieri';
    } else if (days < 7) {
      return `${days} giorni fa`;
    } else {
      return messageDate.toLocaleDateString('it-IT');
    }
  };



  if (selectedConversation) {
    return (
      <div className="chat-detail">
        <div className="chat-header">
          <button onClick={() => setSelectedConversation(null)} className="back-button">
            ← {t('back')}
          </button>
          <div className="chat-participant">
            <div className="participant-avatar">
              {selectedConversation.avatar}
            </div>
            <div className="participant-info">
              <h3>{selectedConversation.participant}</h3>
              <span className="participant-type">{selectedConversation.participantType}</span>
            </div>
          </div>
          <button className="chat-options">⋮</button>
        </div>
        
        <div className="messages-container">
          {messages.map(msg => (
            <div key={msg.id} className={`message ${msg.type}`}>
              <div className="message-bubble">
                <p>{msg.message}</p>
                <span className="message-time">{formatTime(msg.date)}</span>
              </div>
            </div>
          ))}
          <div ref={messagesEndRef} />
        </div>
        
        <div className="message-input-container">
          <input
            type="text"
            placeholder={t('writeMessage') + '...'}
            value={newMessage}
            onChange={(e) => setNewMessage(e.target.value)}
            onKeyPress={(e) => e.key === 'Enter' && sendMessage()}
            className="message-input"
          />
          <button onClick={sendMessage} className="send-button" disabled={!newMessage.trim()}>
            ➤
          </button>
        </div>
      </div>
    );
  }

  return (
    <div className="chat-page">
      <div className="chat-header">
        <h2>{t('messages')}</h2>
        <button className="new-message-button">
          ✉️ {t('newMessage')}
        </button>
      </div>
      
      {loading ? (
        <LoadingSpinner />
      ) : conversations.length === 0 ? (
        <div className="no-messages">
          <span className="no-messages-icon">💬</span>
          <h3>{t('noMessages')}</h3>
          <p>{t('startConversation')}</p>
        </div>
      ) : (
        <div className="conversations-list">
          {conversations.map(conv => (
            <div 
              key={conv.id}
              className="conversation-item"
              onClick={() => selectConversation(conv)}
            >
              <div className="conversation-avatar">
                {conv.avatar}
                {conv.unread > 0 && (
                  <span className="unread-badge">{conv.unread}</span>
                )}
              </div>
              <div className="conversation-content">
                <div className="conversation-header">
                  <h4>{conv.participant}</h4>
                  <span className="conversation-time">{formatTime(conv.lastMessageTime)}</span>
                </div>
                <p className={`last-message ${conv.unread > 0 ? 'unread' : ''}`}>
                  {conv.lastMessage}
                </p>
              </div>
            </div>
          ))}
        </div>
      )}
    </div>
  );
};

