const CoursesPage: React.FC<{ showToast: (message: string, type?: string) => void }> = ({ 
  showToast 
}) => {
  const { user, t } = useAuth();
  const [courses, setCourses] = useState<Course[]>([]);
  const [selectedCourse, setSelectedCourse] = useState<Course | null>(null);
  const [enrolledCourses, setEnrolledCourses] = useState<string[]>([]);
  const [filter, setFilter] = useState('all'); // all, upcoming, past, enrolled
  const [loading, setLoading] = useState(false);

  useEffect(() => {
    fetchCourses();
    if (user?.userType !== 'guest') {
      fetchEnrolledCourses();
    }
  }, [user]);

 const fetchCourses = async () => {
    try {
      setLoading(true);
      const response = await coursesService.getCourses();
      
      if (response.success && response.data) {
        // Mappa i dati per adattarli all'interfaccia Course locale
        const coursesData = response.data.map((course: any) => ({
          id: course._id,
          title: course.title,
          description: course.description,
          date: new Date(course.date),
          cfpCredits: course.cfpCredits,
          price: course.price,
          seatsAvailable: course.seatsAvailable,
          totalSeats: course.totalSeats,
          instructor: course.instructor,
          location: course.location,
          online: course.online,
          enrolled: course.isEnrolled
        }));
        setCourses(coursesData);
      }
    } catch (error) {
      console.error('Error fetching courses:', error);
      showToast('Errore nel caricamento dei corsi', 'error');
    } finally {
      setLoading(false);
    }
  };

  const fetchEnrolledCourses = async () => {
    try {
      const response = await coursesService.getMyEnrollments();
      if (response.success && response.enrollments) {
        const ids = (response.enrollments as any[]).map((e: any) => e.courseId || e._id);
        setEnrolledCourses(ids);
      }
    } catch (error) {
      // Se l'utente non è autenticato o errore, resetta
      setEnrolledCourses([]);
    }
  };

  const [showPaymentModal, setShowPaymentModal] = useState(false);
const [courseToEnroll, setCourseToEnroll] = useState<Course | null>(null);
const [paymentStep, setPaymentStep] = useState<'details' | 'processing' | 'success'>('details');

const enrollInCourse = async (courseId: string) => {
  if (user?.userType === 'guest') {
    showToast('Devi essere registrato per iscriverti ai corsi', 'warning');
    return;
  }

  const course = courses.find(c => c.id === courseId);
  if (!course) return;

  // Se il corso è gratuito, iscrizione diretta tramite API reale
  if (course.price === 0 || course.price < 10) {
    try {
      const response = await coursesService.enrollCourse(courseId);
      if (response.success) {
        setEnrolledCourses(prev => [...prev, courseId]);
        showToast(t('enrollmentCompleted'), 'success');
        setCourses(prev =>
          prev.map(c => c.id === courseId
            ? { ...c, seatsAvailable: Math.max(0, c.seatsAvailable - 1), enrolled: true }
            : c
          )
        );
      } else {
        showToast((response as any).message || 'Errore durante l\'iscrizione', 'error');
      }
    } catch (error: any) {
      showToast(error.message || 'Errore durante l\'iscrizione', 'error');
    }
  } else {
    // Corso a pagamento - apri modal pagamento
    setCourseToEnroll(course);
    setShowPaymentModal(true);
    setPaymentStep('details');
  }
};

const processPayment = async () => {
  if (!courseToEnroll) return;

  setPaymentStep('processing');

  // Simulazione pagamento (per demo - in produzione userebbe Stripe o simile)
  await new Promise(resolve => setTimeout(resolve, 2500));

  try {
    // Chiama API reale per registrare l'iscrizione
    const response = await coursesService.enrollCourse(courseToEnroll.id);
    setPaymentStep('success');
    if (response.success) {
      setEnrolledCourses(prev => [...prev, courseToEnroll.id]);
      setCourses(prev =>
        prev.map(c => c.id === courseToEnroll.id
          ? { ...c, seatsAvailable: Math.max(0, c.seatsAvailable - 1), enrolled: true }
          : c
        )
      );
    }
  } catch (error) {
    setPaymentStep('success'); // Mostra success per la demo anche in caso di errore API
  }

  // Chiudi modal dopo 2 secondi
  setTimeout(() => {
    setShowPaymentModal(false);
    showToast(t('paymentCompletedEnrollment'), 'success');
    setCourseToEnroll(null);
  }, 2000);
};

  const filteredCourses = courses.filter(course => {
    const now = new Date();
    const courseDate = new Date(course.date);
    
    switch (filter) {
      case 'upcoming':
        return courseDate > now;
      case 'past':
        return courseDate < now;
      case 'enrolled':
        return enrolledCourses.includes(course.id);
      default:
        return true;
    }
  });

  if (selectedCourse) {
    return (
      <div className="course-detail">
        <button className="back-button" onClick={() => setSelectedCourse(null)}>
          ← {t('back')}
        </button>
        
        <div className="course-header">
          <div className="course-badge">
            {selectedCourse.online ? '🖥️ Online' : '📍 In presenza'}
          </div>
          <h2>{selectedCourse.title}</h2>
          <p className="course-description">{selectedCourse.description}</p>
        </div>
        
        <div className="course-info-grid">
          <div className="info-card">
            <span className="info-icon">📅</span>
            <div>
              <span className="info-label">{t('courseDate')}</span>
              <span className="info-value">
                {new Date(selectedCourse.date).toLocaleDateString('it-IT', {
                  weekday: 'long',
                  year: 'numeric',
                  month: 'long',
                  day: 'numeric'
                })}
              </span>
            </div>
          </div>
          
          <div className="info-card">
            <span className="info-icon">🎓</span>
            <div>
              <span className="info-label">{t('cfpCredits')}</span>
              <span className="info-value">{selectedCourse.cfpCredits} CFP</span>
            </div>
          </div>
          
          <div className="info-card">
            <span className="info-icon">💰</span>
            <div>
              <span className="info-label">{t('coursePrice')}</span>
              <span className="info-value">€{selectedCourse.price}</span>
            </div>
          </div>
          
          <div className="info-card">
            <span className="info-icon">👨‍🏫</span>
            <div>
              <span className="info-label">{t('courseInstructor')}</span>
              <span className="info-value">{selectedCourse.instructor}</span>
            </div>
          </div>
          
          <div className="info-card">
            <span className="info-icon">📍</span>
            <div>
              <span className="info-label">{t('courseLocation')}</span>
              <span className="info-value">{selectedCourse.location}</span>
            </div>
          </div>
          
          <div className="info-card">
            <span className="info-icon">👥</span>
            <div>
              <span className="info-label">Posti</span>
              <span className="info-value">
                {selectedCourse.seatsAvailable}/{selectedCourse.totalSeats} disponibili
              </span>
            </div>
          </div>
        </div>
        
        <div className="course-enrollment">
          {enrolledCourses.includes(selectedCourse.id) ? (
            <div className="already-enrolled">
              ✅ Sei già iscritto a questo corso
            </div>
          ) : selectedCourse.seatsAvailable === 0 ? (
            <div className="course-full">
              ❌ {t('courseFull')}
            </div>
          ) : user?.userType === 'guest' ? (
            <button className="enroll-button disabled" disabled>
              🔒 Registrati per iscriverti
            </button>
          ) : (
            <button 
              className="enroll-button"
              onClick={() => enrollInCourse(selectedCourse.id)}
            >
              {t('enrollCourse')}
            </button>
          )}
        </div>
        
        <div className="course-additional-info">
          <h3>{t('additionalInfo')}</h3>
          <ul>
            <li>Il corso rilascia {selectedCourse.cfpCredits} crediti formativi professionali</li>
            <li>Attestato di partecipazione incluso</li>
            <li>Materiale didattico fornito</li>
            {selectedCourse.online && <li>Registrazione disponibile per 30 giorni</li>}
          </ul>
        </div>
      </div>
    );
  }

  return (
    <div className="courses-page">
      {/* Modal Pagamento Simulato */}
{showPaymentModal && courseToEnroll && (
  <div className="payment-modal-overlay" onClick={() => paymentStep === 'details' && setShowPaymentModal(false)}>
    <div className="payment-modal" onClick={(e) => e.stopPropagation()}>
      {paymentStep === 'details' && (
        <>
          <div className="payment-header">
            <h3>💳 Pagamento Corso</h3>
            <button className="close-modal" onClick={() => setShowPaymentModal(false)}>×</button>
          </div>
          
          <div className="payment-course-info">
            <h4>{courseToEnroll.title}</h4>
            <div className="payment-details">
              <p>📅 Data: {new Date(courseToEnroll.date).toLocaleDateString('it-IT')}</p>
              <p>🎓 CFP: {courseToEnroll.cfpCredits} crediti</p>
              <p className="payment-price">💰 Totale: €{courseToEnroll.price}</p>
            </div>
          </div>
          
          <div className="payment-form">
            <h4>🔒 Pagamento Sicuro (DEMO)</h4>
            <div className="form-group">
              <label>Numero Carta</label>
              <input type="text" placeholder="4242 4242 4242 4242" disabled />
            </div>
            <div className="form-row">
              <div className="form-group">
                <label>Scadenza</label>
                <input type="text" placeholder="12/25" disabled />
              </div>
              <div className="form-group">
                <label>CVV</label>
                <input type="text" placeholder="123" disabled />
              </div>
            </div>
            <div className="form-group">
              <label>Nome Intestatario</label>
              <input type="text" value={`${user?.firstName} ${user?.lastName}`} disabled />
            </div>
          </div>
          
          <div className="payment-disclaimer">
            ⚠️ <strong>DEMO:</strong> Questo è un pagamento simulato per test. 
            {t('noChargeWillBeMade')}.
          </div>
          
          <div className="payment-actions">
            <button className="cancel-button" onClick={() => setShowPaymentModal(false)}>
              Annulla
            </button>
            <button className="pay-button" onClick={processPayment}>
              Paga €{courseToEnroll.price}
            </button>
          </div>
        </>
      )}
      
      {paymentStep === 'processing' && (
        <div className="payment-processing">
          <LoadingSpinner />
          <h3>Elaborazione pagamento...</h3>
          <p>Non chiudere questa finestra</p>
        </div>
      )}
      
      {paymentStep === 'success' && (
        <div className="payment-success">
          <div className="success-icon">✅</div>
          <h3>{t('paymentCompleted')}</h3>
          <p>{t('enrollmentConfirmedFor')}</p>
          <h4>{courseToEnroll.title}</h4>
          <p>Riceverai una email di conferma</p>
        </div>
      )}
    </div>
  </div>
)}
      <div className="courses-header">
        <h2>{t('courses')} CFP</h2>
        <div className="courses-filters">
          <button 
            className={filter === 'all' ? 'active' : ''}
            onClick={() => setFilter('all')}
          >
            Tutti
          </button>
          <button 
            className={filter === 'upcoming' ? 'active' : ''}
            onClick={() => setFilter('upcoming')}
          >
            Prossimi
          </button>
          <button 
            className={filter === 'past' ? 'active' : ''}
            onClick={() => setFilter('past')}
          >
            Passati
          </button>
          {user?.userType !== 'guest' && (
            <button 
              className={filter === 'enrolled' ? 'active' : ''}
              onClick={() => setFilter('enrolled')}
            >
              I miei corsi
            </button>
          )}
        </div>
      </div>
      
      {loading ? (
        <LoadingSpinner />
      ) : filteredCourses.length === 0 ? (
        <div className="no-courses">
          <span className="no-courses-icon">📚</span>
          <h3>{t('noCourseFound')}</h3>
          <p>Controlla più tardi per nuovi corsi</p>
        </div>
      ) : (
        <div className="courses-list">
          {filteredCourses.map(course => {
            const isEnrolled = enrolledCourses.includes(course.id);
            const isPast = new Date(course.date) < new Date();
            
            return (
              <div key={course.id} className="course-card">
                <div className="course-header">
                  <div className="course-badges">
                    {course.online && <span className="badge online">Online</span>}
                    {isEnrolled && <span className="badge enrolled">Iscritto</span>}
                    {isPast && <span className="badge past">Concluso</span>}
                  </div>
                  <h3>{course.title}</h3>
                </div>
                
                <p className="course-description">{course.description}</p>
                
                <div className="course-details">
                  <span>📅 {new Date(course.date).toLocaleDateString('it-IT')}</span>
                  <span>⏰ {new Date(course.date).toLocaleTimeString('it-IT', { hour: '2-digit', minute: '2-digit' })}</span>
                  <span>🎓 {course.cfpCredits} CFP</span>
                  <span>💰 €{course.price}</span>
                </div>
                
                <div className="course-instructor">
                  <span>👨‍🏫 {course.instructor}</span>
                  <span>📍 {course.location}</span>
                </div>
                
                <div className="course-availability">
                  {course.seatsAvailable > 0 ? (
                    <div className="seats-bar">
                      <div 
                        className="seats-filled"
                        style={{ width: `${((course.totalSeats - course.seatsAvailable) / course.totalSeats) * 100}%` }}
                      />
                    </div>
                  ) : (
                    <span className="course-full-badge">COMPLETO</span>
                  )}
                  <span className="seats-text">
                    {course.seatsAvailable > 0 
                      ? `${course.seatsAvailable} posti disponibili su ${course.totalSeats}`
                      : t('noSeatsAvailable')
                    }
                  </span>
                </div>
                
                <button 
                  className="view-course-button"
                  onClick={() => setSelectedCourse(course)}
                >
                  {t('courseDetails')} →
                </button>
              </div>
            );
          })}
        </div>
      )}
    </div>
  );
};

