// Componente per attivazione profilo architetto
const ActivateArchitectProfile: React.FC<{
  onBack: () => void;
  showToast: (message: string, type?: string) => void;
}> = ({ onBack, showToast }) => {
  const { activateArchitectProfile, t } = useAuth();
  const [formData, setFormData] = useState({
    token: '',
    orderNumber: ''
  });
  const [loading, setLoading] = useState(false);
  const [errors, setErrors] = useState<any>({});

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    
    const newErrors: any = {};
    if (!formData.token) newErrors.token = 'Token richiesto';
    if (!formData.orderNumber) newErrors.orderNumber = 'Numero ordine richiesto';
    
    if (Object.keys(newErrors).length > 0) {
      setErrors(newErrors);
      return;
    }
    
    setLoading(true);
    const result = await activateArchitectProfile(formData.token, formData.orderNumber);
    setLoading(false);
    
    if (result.success) {
      showToast(t('profileActivated'), 'success');
      onBack();
    } else {
      showToast(result.error || t('invalidToken'), 'error');
    }
  };

  return (
    <div className="activate-profile-page">
      <div className="section-header">
        <button onClick={onBack}>← {t('back')}</button>
        <h3>{t('activateProfile')}</h3>
      </div>
      
      <div className="activate-form">
        <div className="info-box">
          <span className="info-icon">ℹ️</span>
          <p>
            Per attivare il tuo profilo architetto, inserisci il token di attivazione
            che ti è stato fornito dalla segreteria tramite PEC insieme al tuo numero d'ordine.
          </p>
        </div>
        
        <form onSubmit={handleSubmit}>
          <div className="form-group">
            <label>Numero Ordine</label>
            <input
              type="text"
              placeholder="Es: 1234"
              value={formData.orderNumber}
              onChange={(e) => {
                setFormData({...formData, orderNumber: e.target.value});
                setErrors({...errors, orderNumber: undefined});
              }}
              className={errors.orderNumber ? 'error' : ''}
            />
            {errors.orderNumber && <span className="error-message">{errors.orderNumber}</span>}
          </div>
          
          <div className="form-group">
            <label>Token di Attivazione</label>
            <input
              type="text"
              placeholder="Es: TOKEN-ARCH-XXXX-2025"
              value={formData.token}
              onChange={(e) => {
                setFormData({...formData, token: e.target.value});
                setErrors({...errors, token: undefined});
              }}
              className={errors.token ? 'error' : ''}
            />
            {errors.token && <span className="error-message">{errors.token}</span>}
          </div>
          
          <button type="submit" disabled={loading} className="submit-button">
            {loading ? <LoadingSpinner /> : t('activateProfile')}
          </button>
        </form>
        
        <div className="test-token-info">
          <h4>🧪 Token di test disponibili:</h4>
          <div className="token-example">
            <code>ARCH-TOKEN-2025-001</code>
            <p>Numero ordine: <strong>2001</strong></p>
          </div>
          <div className="token-example">
            <code>ARCH-TOKEN-2025-002</code>
            <p>Numero ordine: <strong>2002</strong></p>
          </div>
        </div>
      </div>
    </div>
  );
};

// Edit Profile View
const EditProfileView: React.FC<{
  onBack: () => void;
  showToast: (message: string, type?: string) => void;
}> = ({ onBack, showToast }) => {
  const { user, t } = useAuth();
  const [formData, setFormData] = useState({
    firstName: user?.firstName || '',
    lastName: user?.lastName || '',
    phone: user?.phone || '',
    bio: user?.bio || '',
    specialties: [] as string[],
    services: [] as string[],
    location: 'Caltanissetta'
  });
  const [photoUploading, setPhotoUploading] = useState(false);
  const [photoPreview, setPhotoPreview] = useState<string | null>((user as any)?.photoUrl ? `${SERVER_BASE}${(user as any).photoUrl}` : null);
  const photoInputRef = React.useRef<HTMLInputElement>(null);

  // Carica dati architetto se è un architetto verificato
  useEffect(() => {
    const loadArchitectData = async () => {
      if (user?.userType === 'architect' && user?.isVerified) {
        // Prima prova da user.architect in localStorage
        if (user.architect) {
          setFormData(prev => ({
            ...prev,
            bio: user.architect?.bio || '',
            specialties: user.architect?.specialties || [],
            services: (user.architect as any)?.services || [],
            location: user.architect?.location || 'Caltanissetta'
          }));
        } else {
          // Fallback: carica tutti gli architetti e trova per userId
          try {
            const response = await architectsService.getArchitects({});
            if (response.success && response.data) {
              const userId = user._id || user.id;
              const myArchitect = (response.data as any[]).find((a: any) => a.userId === userId);
              if (myArchitect) {
                setFormData(prev => ({
                  ...prev,
                  bio: myArchitect.bio || '',
                  specialties: myArchitect.specialties || [],
                  services: myArchitect.services || [],
                  location: myArchitect.location || 'Caltanissetta'
                }));
              }
            }
          } catch (error) {
            console.error('Errore caricamento dati architetto:', error);
          }
        }
      }
    };

    loadArchitectData();
  }, [user]);

  const handlePhotoUpload = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;

    // Preview immediata
    const reader = new FileReader();
    reader.onload = (ev) => setPhotoPreview(ev.target?.result as string);
    reader.readAsDataURL(file);

    // Upload al backend
    setPhotoUploading(true);
    try {
      const formDataUpload = new FormData();
      formDataUpload.append('photo', file);
      const token = localStorage.getItem('token');
      const res = await fetch(`${API_BASE}/upload/profile-photo`, {
        method: 'POST',
        headers: token ? { Authorization: `Bearer ${token}` } : {},
        body: formDataUpload
      });
      if (!res.ok) {
        const errData = await res.json().catch(() => ({}));
        showToast(errData.message || `Errore upload (${res.status})`, 'error');
        setPhotoPreview(null);
        return;
      }
      const data = await res.json();
      if (data.success) {
        showToast('Foto profilo aggiornata!', 'success');
        // Aggiorna user in localStorage con nuova foto
        const savedUser = localStorage.getItem('user');
        if (savedUser) {
          const u = JSON.parse(savedUser);
          localStorage.setItem('user', JSON.stringify({ ...u, photoUrl: data.photoUrl }));
        }
      } else {
        showToast(data.message || 'Errore upload foto', 'error');
        setPhotoPreview(null);
      }
    } catch (err) {
      showToast('Errore durante l\'upload della foto', 'error');
    } finally {
      setPhotoUploading(false);
    }
  };

  const handleSave = async () => {
    try {
      // Usa _id oppure id
      const userId = user?._id || user?.id;
      
      if (!userId) {
        showToast('Errore: utente non identificato', 'error');
        return;
      }

      const userResponse = await usersService.updateUser(userId, {
        firstName: formData.firstName,
        lastName: formData.lastName,
        phone: formData.phone
      });

      if (user.userType === 'architect' && user.isVerified) {
        await architectsService.updateMyProfile({
          bio: formData.bio,
          specialties: formData.specialties,
          services: formData.services,
          location: formData.location
        });
      }

      if (userResponse.success) {
        showToast('Profilo aggiornato con successo', 'success');

        const updatedUser = {
          ...user,
          firstName: formData.firstName,
          lastName: formData.lastName,
          phone: formData.phone,
          ...(user.architect && {
            architect: {
              ...user.architect,
              bio: formData.bio,
              specialties: formData.specialties,
              services: formData.services,
              location: formData.location
            }
          })
        };
        
        localStorage.setItem('user', JSON.stringify(updatedUser));
        //console.log('✅ SALVATO NEL LOCALSTORAGE:', updatedUser);

        window.location.reload();
      }
    } catch (error) {
      console.error('Errore aggiornamento profilo:', error);
      showToast('Errore durante il salvataggio', 'error');
    }
  };

  return (
    <div className="edit-profile-view">
      <div className="section-header">
        <button onClick={onBack}>← {t('back')}</button>
        <h3>{t('editProfile')}</h3>
      </div>
      
      <div className="edit-form">
        {/* Sezione foto profilo */}
        <div className="form-section photo-section">
          <h4>Foto Profilo</h4>
          <div className="photo-upload-area">
            <div className="profile-photo-preview" onClick={() => photoInputRef.current?.click()} style={{ cursor: 'pointer' }}>
              {photoPreview ? (
                <img src={photoPreview} alt="Foto profilo" style={{ width: 80, height: 80, borderRadius: '50%', objectFit: 'cover', border: '3px solid #667eea' }} />
              ) : (
                <div style={{ width: 80, height: 80, borderRadius: '50%', background: 'linear-gradient(135deg, #667eea, #764ba2)', display: 'flex', alignItems: 'center', justifyContent: 'center', fontSize: 28, color: 'white', border: '3px solid #667eea' }}>
                  {user?.firstName?.[0]}{user?.lastName?.[0]}
                </div>
              )}
              <div className="photo-overlay" style={{ position: 'absolute', bottom: 0, right: 0, background: '#667eea', borderRadius: '50%', width: 26, height: 26, display: 'flex', alignItems: 'center', justifyContent: 'center', fontSize: 14 }}>
                📷
              </div>
            </div>
            <div className="photo-upload-info">
              <button
                type="button"
                className="photo-upload-btn"
                onClick={() => photoInputRef.current?.click()}
                disabled={photoUploading}
                style={{ background: '#667eea', color: 'white', border: 'none', borderRadius: 8, padding: '8px 16px', cursor: 'pointer', fontSize: 14 }}
              >
                {photoUploading ? '⏳ Caricamento...' : '📷 Cambia foto'}
              </button>
              <p style={{ fontSize: 12, color: '#888', margin: '4px 0 0' }}>JPG, PNG, WebP • Max 5MB</p>
            </div>
            <input
              ref={photoInputRef}
              type="file"
              accept="image/jpeg,image/jpg,image/png,image/webp"
              style={{ display: 'none' }}
              onChange={handlePhotoUpload}
            />
          </div>
        </div>

        <div className="form-section">
          <h4>{t('personalInfo')}</h4>

          <div className="form-group">
            <label>Nome</label>
            <input
              type="text"
              value={formData.firstName}
              onChange={(e) => setFormData({...formData, firstName: e.target.value})}
            />
          </div>
          
          <div className="form-group">
            <label>Cognome</label>
            <input
              type="text"
              value={formData.lastName}
              onChange={(e) => setFormData({...formData, lastName: e.target.value})}
            />
          </div>
          
          <div className="form-group">
            <label>Telefono</label>
            <input
              type="tel"
              value={formData.phone}
              onChange={(e) => setFormData({...formData, phone: e.target.value})}
            />
          </div>
        </div>
        
        {user?.userType === 'architect' && user?.isVerified && (
          <div className="form-section">
            <h4>{t('professionalInfo')}</h4>
            
            <div className="form-group">
              <label>{t('bio')}</label>
              <textarea
                value={formData.bio}
                onChange={(e) => setFormData({...formData, bio: e.target.value})}
                rows={4}
                placeholder="Descrivi la tua esperienza professionale..."
              />
            </div>
            
            <div className="form-group">
              <label>Località</label>
              <select 
                value={formData.location}
                onChange={(e) => setFormData({...formData, location: e.target.value})}
              >
                <option value="Caltanissetta">Caltanissetta</option>
                <option value="San Cataldo">San Cataldo</option>
                <option value="Gela">Gela</option>
                <option value="Niscemi">Niscemi</option>
              </select>
            </div>
          </div>
        )}
        
        <button onClick={handleSave} className="save-button">
          {t('save')}
        </button>
      </div>
    </div>
  );
};

