// PROFILE PAGE PRINCIPALE
const ProfilePage: React.FC<{ showToast: (message: string, type?: string) => void }> = ({ 
  showToast 
}) => {
  const { user, logout, t } = useAuth();
  const [activeSection, setActiveSection] = useState<string | null>(null);

  const handleLogout = () => {
    logout();
    showToast(t('logout') + ' completato', 'success');
  };

  // Render sottosezioni
  if (activeSection === 'activate') {
    return (
      <ActivateArchitectProfile 
        onBack={() => setActiveSection(null)} 
        showToast={showToast}
      />
    );
  }

  if (activeSection === 'edit') {
    return <EditProfileView onBack={() => setActiveSection(null)} showToast={showToast} />;
  }

  if (activeSection === 'settings') {
    return <SettingsView onBack={() => setActiveSection(null)} showToast={showToast} />;
  }

  if (activeSection === 'certificates') {
    return <CertificatesView onBack={() => setActiveSection(null)} showToast={showToast} />;
  }

  if (activeSection === 'help') {
    return <HelpView onBack={() => setActiveSection(null)} showToast={showToast} />;
  }

  if (activeSection === 'about') {
    return <AboutView onBack={() => setActiveSection(null)} showToast={showToast} />;
  }

  return (
    <div className="profile-page">
      <div className="profile-header">
        <div className="profile-avatar-large">
          {user?.firstName?.[0]}{user?.lastName?.[0]}
        </div>
        <h2>
          {user?.userType === 'architect' && user?.isVerified ? 'Arch. ' : ''}
          {user?.firstName} {user?.lastName}
        </h2>
        <p className="profile-email">{user?.email || 'Ospite'}</p>
        <div className={`user-type ${user?.userType}`}>
          {user?.userType === 'admin' ? (
            <>🔑 Amministratore Sistema</>
          ) : user?.userType === 'architect' && user?.isVerified ? (
            <>✅ Architetto Verificato</>
          ) : user?.userType === 'architect' && !user?.isVerified ? (
            <>⏳ Architetto Non Verificato</>
          ) : user?.userType === 'registered' ? (
            <>👤 Utente Registrato</>
          ) : (
            <>👋 Ospite</>
          )}
        </div>
        {user?.orderNumber && (
          <p className="order-number">N. Ordine: {user.orderNumber}</p>
        )}
      </div>

      <div className="profile-menu">
        {/* Mostra opzione attivazione solo per utenti registrati non verificati */}
        {user?.userType === 'registered' && !user?.isVerified && (
          <button className="menu-item activate" onClick={() => setActiveSection('activate')}>
            <span className="menu-icon">🎫</span>
            <span>{t('activateProfile')}</span>
            <span className="menu-arrow">→</span>
          </button>
        )}
        
        <button className="menu-item" onClick={() => setActiveSection('edit')}>
          <span className="menu-icon">✏️</span>
          <span>{t('editProfile')}</span>
          <span className="menu-arrow">→</span>
        </button>
        
        <button className="menu-item" onClick={() => setActiveSection('settings')}>
          <span className="menu-icon">⚙️</span>
          <span>{t('settings')}</span>
          <span className="menu-arrow">→</span>
        </button>
        
        {user?.userType === 'architect' && user?.isVerified && (
          <button className="menu-item" onClick={() => setActiveSection('certificates')}>
            <span className="menu-icon">📜</span>
            <span>{t('certificates')}</span>
            <span className="menu-arrow">→</span>
          </button>
        )}
        
        <button className="menu-item" onClick={() => setActiveSection('help')}>
          <span className="menu-icon">❓</span>
          <span>{t('help')}</span>
          <span className="menu-arrow">→</span>
        </button>
        
        <button className="menu-item" onClick={() => setActiveSection('about')}>
          <span className="menu-icon">ℹ️</span>
          <span>{t('about')}</span>
          <span className="menu-arrow">→</span>
        </button>
        
        {user?.userType !== 'guest' && (
          <button className="menu-item logout" onClick={handleLogout}>
            <span className="menu-icon">🚪</span>
            <span>{t('logout')}</span>
            <span className="menu-arrow">→</span>
          </button>
        )}
      </div>

      <div className="app-info">
        <p>Versione 1.0.0</p>
        <p>© 2025 Ordine Architetti P.P.C. Caltanissetta</p>
      </div>
    </div>
  );
};

// =====================================
// MAIN APP COMPONENT
// =====================================

const App: React.FC = () => {
  const { user, logout } = useAuth();
  const [showSplash, setShowSplash] = useState(true);
  const [showOnboarding, setShowOnboarding] = useState(false);
  const [currentPage, setCurrentPage] = useState('home');
  const [toast, setToast] = useState<{ message: string; type: string } | null>(null);
  const [unreadMessages, setUnreadMessages] = useState(0);
  const [resetToken, setResetToken] = useState<string | null>(() => {
    const params = new URLSearchParams(window.location.search);
    return params.get('resetToken');
  });

  useEffect(() => {
    // Show splash screen for 2 seconds
    const timer = setTimeout(() => {
      setShowSplash(false);
      // Check if user has seen onboarding
      const hasSeenOnboarding = localStorage.getItem('hasSeenOnboarding');
      if (!hasSeenOnboarding && !user) {
        setShowOnboarding(true);
      }
    }, 2000);

    return () => clearTimeout(timer);
  }, [user]);

  // Fetch unread messages count periodically
  useEffect(() => {
    if (!user || user.userType === 'guest') {
      setUnreadMessages(0);
      return;
    }
    const fetchUnread = async () => {
      try {
        const token = localStorage.getItem('token');
        if (!token) return;
        const res = await fetch(`${API_BASE}/messages/conversations`, {
          headers: { Authorization: `Bearer ${token}` }
        });
        if (res.ok) {
          const data = await res.json();
          if (data.success && Array.isArray(data.conversations)) {
            const total = data.conversations.reduce((sum: number, c: any) => sum + (c.unreadCount || 0), 0);
            setUnreadMessages(total);
          }
        }
      } catch {}
    };
    fetchUnread();
    const interval = setInterval(fetchUnread, 30000); // ogni 30 secondi
    return () => clearInterval(interval);
  }, [user]);

  const completeOnboarding = () => {
    localStorage.setItem('hasSeenOnboarding', 'true');
    setShowOnboarding(false);
  };

  const showToast = (message: string, type = 'info') => {
    setToast({ message, type });
    setTimeout(() => setToast(null), 3000);
  };

  if (showSplash) {
    return <SplashScreen />;
  }

  if (showOnboarding) {
    return <OnboardingScreen onComplete={completeOnboarding} />;
  }

  if (resetToken) {
    return (
      <div className="app">
        {toast && <Toast {...toast} onClose={() => setToast(null)} />}
        <ResetPasswordScreen
          token={resetToken}
          showToast={showToast}
          onDone={() => setResetToken(null)}
        />
      </div>
    );
  }

  return (
    <div className="app">
      {toast && <Toast {...toast} onClose={() => setToast(null)} />}

      {!user ? (
        <AuthScreen showToast={showToast} />
      ) : (
        <>
          <AppHeader user={user} onLogout={() => logout()} />
          
          <main className="app-main">
            {currentPage === 'home' && <HomePage showToast={showToast} setCurrentPage={setCurrentPage} />}
{currentPage === 'search' && <SearchPage showToast={showToast} setCurrentPage={setCurrentPage} />}{currentPage === 'chat' && <ChatPage showToast={showToast} />}{currentPage === 'courses' && <CoursesPage showToast={showToast} />}{currentPage === 'profile' && <ProfilePage showToast={showToast} />}          </main>
          
          <BottomNav
            currentPage={currentPage}
            setCurrentPage={(page) => {
              if (page === 'chat') setUnreadMessages(0); // reset badge when opening chat
              setCurrentPage(page);
            }}
            userType={user.userType}
            unreadMessages={unreadMessages}
          />
        </>
      )}
    </div>
  );
};

const Root: React.FC = () => {
  return (
    <BrowserRouter>              {/* ← Router per gestire URL */}
      <Routes>                    {/* ← Container delle route */}
        
        {/* Quando vai su /admin/* mostra AdminApp */}
        <Route path="/admin/*" element={<AdminApp />} />
        
        {/* Quando vai su qualsiasi altra URL mostra App normale */}
        <Route path="/*" element={
          <AuthProvider>         {/* ← App normale con AuthProvider */}
            <App />
          </AuthProvider>
        } />
        
      </Routes>
    </BrowserRouter>
  );
};

export default Root;