import React, { useState, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import { adminUsersService } from '../services/adminApi';

const AdminUsers: React.FC = () => {
  const navigate = useNavigate();
  const [users, setUsers] = useState<any[]>([]);
  const [loading, setLoading] = useState(true);
  const [search, setSearch] = useState('');

  useEffect(() => {
    fetchUsers();
  }, []);

  const fetchUsers = async () => {
    try {
      setLoading(true);
      const response: any = await adminUsersService.getAll({ search });
      if (response.data) setUsers(response.data);
    } catch (error) {
      console.error(error);
    } finally {
      setLoading(false);
    }
  };

  const toggleStatus = async (id: string, isActive: boolean) => {
    try {
      if (isActive) {
        await adminUsersService.deactivate(id);
      } else {
        await adminUsersService.activate(id);
      }
      fetchUsers();
    } catch (error) {
      alert('Errore');
    }
  };

  const deleteUser = async (id: string) => {
    if (!window.confirm('Eliminare questo utente?')) return;
    try {
      await adminUsersService.delete(id);
      fetchUsers();
    } catch (error) {
      alert('Errore');
    }
  };

  return (
    <div style={{ padding: '20px', background: '#f5f5f5', minHeight: '100vh' }}>
      <button onClick={() => navigate('/admin/dashboard')} style={{ marginBottom: '20px', padding: '10px 20px', cursor: 'pointer' }}>
        ← Dashboard
      </button>

      <h1>👥 Gestione Utenti</h1>

      <input
        type="text"
        placeholder="🔍 Cerca per email o nome..."
        value={search}
        onChange={(e) => setSearch(e.target.value)}
        onKeyPress={(e) => e.key === 'Enter' && fetchUsers()}
        style={{ padding: '12px', width: '100%', maxWidth: '400px', marginBottom: '20px', fontSize: '16px' }}
      />

      {loading ? (
        <p>Caricamento...</p>
      ) : (
        <table style={{ width: '100%', background: 'white', borderCollapse: 'collapse' }}>
          <thead>
            <tr style={{ background: '#667eea', color: 'white' }}>
              <th style={{ padding: '12px', textAlign: 'left' }}>Email</th>
              <th style={{ padding: '12px', textAlign: 'left' }}>Nome</th>
              <th style={{ padding: '12px', textAlign: 'left' }}>Tipo</th>
              <th style={{ padding: '12px', textAlign: 'left' }}>Stato</th>
              <th style={{ padding: '12px', textAlign: 'left' }}>Azioni</th>
            </tr>
          </thead>
          <tbody>
            {users.map((user) => (
              <tr key={user._id} style={{ borderBottom: '1px solid #ddd' }}>
                <td style={{ padding: '12px' }}>{user.email}</td>
                <td style={{ padding: '12px' }}>{user.firstName} {user.lastName}</td>
                <td style={{ padding: '12px' }}>{user.userType}</td>
                <td style={{ padding: '12px' }}>
                  <span style={{ color: user.isActive ? 'green' : 'red' }}>
                    {user.isActive ? '✅ Attivo' : '❌ Disattivo'}
                  </span>
                </td>
                <td style={{ padding: '12px' }}>
                  <button onClick={() => toggleStatus(user._id, user.isActive)} style={{ marginRight: '10px', padding: '5px 10px', cursor: 'pointer' }}>
                    {user.isActive ? 'Disattiva' : 'Attiva'}
                  </button>
                  <button onClick={() => deleteUser(user._id)} style={{ padding: '5px 10px', background: '#e74c3c', color: 'white', border: 'none', cursor: 'pointer' }}>
                    🗑️ Elimina
                  </button>
                </td>
              </tr>
            ))}
          </tbody>
        </table>
      )}

      <p style={{ marginTop: '20px', color: '#666' }}>
        Totale utenti: {users.length}
      </p>
    </div>
  );
};

export default AdminUsers;