// src/services/messages.service.ts
// Servizio per gestione messaggi e conversazioni

import api from './api';

// ============================================
// INTERFACCE
// ============================================

export interface Message {
  _id: string;
  conversationId: string;
  senderId: string;
  content: string;
  readAt?: string;
  createdAt: string;
  updatedAt?: string;
  sender?: {
    id: string;
    firstName: string;
    lastName: string;
  };
  isOwn?: boolean;
}

export interface Conversation {
  _id: string;
  type: 'direct' | 'group';
  participants: string[];
  name?: string;
  createdAt: string;
  updatedAt: string;
  participant?: {
    id: string;
    firstName: string;
    lastName: string;
    userType: string;
    isArchitect: boolean;
  };
  lastMessage?: {
    content: string;
    createdAt: string;
    isOwn: boolean;
  };
  unreadCount: number;
}

// ============================================
// SERVIZIO MESSAGGI
// ============================================

const messagesService = {
  /**
   * Ottieni lista conversazioni dell'utente
   */
  getConversations: async () => {
    return api.get('/messages/conversations');
  },

  /**
   * Ottieni messaggi di una conversazione specifica
   */
  getConversationMessages: async (conversationId: string) => {
    return api.get(`/messages/conversations/${conversationId}`);
  },

  /**
   * Crea nuova conversazione o ottieni esistente
   */
  createConversation: async (recipientId: string) => {
    return api.post('/messages/conversations', { recipientId });
  },

  /**
   * Invia messaggio in una conversazione
   */
  sendMessage: async (conversationId: string, content: string) => {
    return api.post(`/messages/conversations/${conversationId}/messages`, { content });
  },

  /**
   * Ottieni conteggio messaggi non letti
   */
  getUnreadCount: async () => {
    return api.get('/messages/unread-count');
  },
};

export default messagesService;