import React from 'react';
import { Routes, Route, Navigate, useLocation } from 'react-router-dom';
import Sidebar from './components/Sidebar';
import AdminLogin from './pages/AdminLogin';
import AdminDashboard from './pages/AdminDashboard';
import AdminUsers from './pages/AdminUsers';
import AdminArchitects from './pages/AdminArchitects';
import AdminArchitectsPending from './pages/AdminArchitectsPending';
import AdminTokens from './pages/AdminTokens';
import AdminNews from './pages/AdminNews';
import AdminCourses from './pages/AdminCourses';
import AdminStatistics from './pages/AdminStatistics';

const AdminApp: React.FC = () => {
  const location = useLocation();
  const isLoginPage = location.pathname === '/admin/login' || location.pathname === '/admin';

  return (
    <div style={{ display: 'flex', minHeight: '100vh' }}>
      {!isLoginPage && <Sidebar />}
      
      <div style={{ 
        flex: 1, 
        marginLeft: !isLoginPage ? '250px' : '0',
        background: '#f5f6fa',
        minHeight: '100vh'
      }}>
        <Routes>
          <Route path="/" element={<Navigate to="/admin/login" replace />} />
          <Route path="/login" element={<AdminLogin />} />
          <Route path="/dashboard" element={<AdminDashboard />} />
          <Route path="/users" element={<AdminUsers />} />
          <Route path="/architects" element={<AdminArchitects />} />
          <Route path="/architects/pending" element={<AdminArchitectsPending />} />
          <Route path="/tokens" element={<AdminTokens />} />
          <Route path="/news" element={<AdminNews />} />
          <Route path="/courses" element={<AdminCourses />} />
          <Route path="/statistics" element={<AdminStatistics />} />
        </Routes>
      </div>
    </div>
  );
};

export default AdminApp;