import React, { useState, useEffect } from 'react';
import { API_BASE_URL } from '../services/adminApi';
import axios from 'axios';
import '../styles/AdminNews.css';

interface News {
  _id: string;
  title: string;
  excerpt: string;
  content: string;
  date: string;
  category: string;
  author: string;
  important: boolean;
  isPublished: boolean;
  createdAt: string;
}

const AdminNews: React.FC = () => {
  const [newsList, setNewsList] = useState<News[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState('');
  const [filter, setFilter] = useState<'all' | 'published' | 'draft'>('all');
  const [search, setSearch] = useState('');
  const [showForm, setShowForm] = useState(false);
  const [editingNews, setEditingNews] = useState<News | null>(null);
  const [stats, setStats] = useState({ total: 0, published: 0, draft: 0, important: 0 });

  const [formData, setFormData] = useState({
    title: '',
    excerpt: '',
    content: '',
    category: 'Generica',
    author: 'Admin',
    important: false,
    isPublished: true
  });

  useEffect(() => {
    loadNews();
    loadStats();
  }, [filter]);

  const loadNews = async () => {
    try {
      setLoading(true);
      const token = localStorage.getItem('adminToken');
      
      const params: any = {};
      if (filter === 'published') params.isPublished = 'true';
      if (filter === 'draft') params.isPublished = 'false';

      const response = await axios.get(`${API_BASE_URL}/news`, {
        headers: { Authorization: `Bearer ${token}` },
        params
      });

      setNewsList(response.data.data || []);
      setError('');
    } catch (err: any) {
      console.error('Errore caricamento news:', err);
      setError(err.response?.data?.message || 'Errore nel caricamento');
    } finally {
      setLoading(false);
    }
  };

  const loadStats = async () => {
    try {
      const token = localStorage.getItem('adminToken');
      const response = await axios.get(`${API_BASE_URL}/news/stats`, {
        headers: { Authorization: `Bearer ${token}` }
      });
      setStats(response.data.stats);
    } catch (err) {
      console.error('Errore caricamento statistiche:', err);
    }
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();

    if (!formData.title || !formData.content) {
      alert('⚠️ Titolo e contenuto richiesti');
      return;
    }

    try {
      const token = localStorage.getItem('adminToken');

      if (editingNews) {
        // Update
        await axios.put(
          `${API_BASE_URL}/news/${editingNews._id}`,
          formData,
          { headers: { Authorization: `Bearer ${token}` } }
        );
        alert('✅ News aggiornata con successo!');
      } else {
        // Create
        await axios.post(
          `${API_BASE_URL}/news`,
          formData,
          { headers: { Authorization: `Bearer ${token}` } }
        );
        alert('✅ News creata con successo!');
      }

      setShowForm(false);
      setEditingNews(null);
      resetForm();
      loadNews();
      loadStats();
    } catch (err: any) {
      alert(err.response?.data?.message || 'Errore nell\'operazione');
    }
  };

  const handleEdit = (news: News) => {
    setEditingNews(news);
    setFormData({
      title: news.title,
      excerpt: news.excerpt,
      content: news.content,
      category: news.category,
      author: news.author,
      important: news.important,
      isPublished: news.isPublished
    });
    setShowForm(true);
  };

  const handleDelete = async (id: string) => {
    if (!window.confirm('Sei sicuro di voler eliminare questa news?')) {
      return;
    }

    try {
      const token = localStorage.getItem('adminToken');
      await axios.delete(`${API_BASE_URL}/news/${id}`, {
        headers: { Authorization: `Bearer ${token}` }
      });

      alert('✅ News eliminata');
      loadNews();
      loadStats();
    } catch (err: any) {
      alert(err.response?.data?.message || 'Errore nell\'eliminazione');
    }
  };

  const handleTogglePublish = async (news: News) => {
    try {
      const token = localStorage.getItem('adminToken');
      const endpoint = news.isPublished ? 'unpublish' : 'publish';
      
      await axios.post(
        `${API_BASE_URL}/news/${news._id}/${endpoint}`,
        {},
        { headers: { Authorization: `Bearer ${token}` } }
      );

      alert(`✅ News ${news.isPublished ? 'nascosta' : 'pubblicata'} con successo!`);
      loadNews();
      loadStats();
    } catch (err: any) {
      alert(err.response?.data?.message || 'Errore nell\'operazione');
    }
  };

  const resetForm = () => {
    setFormData({
      title: '',
      excerpt: '',
      content: '',
      category: 'Generica',
      author: 'Admin',
      important: false,
      isPublished: true
    });
  };

  const filteredNews = newsList.filter(news => {
    const searchLower = search.toLowerCase();
    return (
      news.title?.toLowerCase().includes(searchLower) ||
      news.excerpt?.toLowerCase().includes(searchLower) ||
      news.category?.toLowerCase().includes(searchLower)
    );
  });

  if (loading) {
    return (
      <div className="admin-news">
        <div className="loading">Caricamento news...</div>
      </div>
    );
  }

  return (
    <div className="admin-news">
      <div className="page-header">
        <h1>📰 Gestione News</h1>
        <button onClick={() => { setShowForm(true); setEditingNews(null); resetForm(); }} className="btn btn-primary">
          ➕ Nuova News
        </button>
      </div>

      <div className="stats-grid">
        <div className="stat-card">
          <div className="stat-icon">📊</div>
          <div className="stat-content">
            <span className="stat-value">{stats.total}</span>
            <span className="stat-label">Totale</span>
          </div>
        </div>
        <div className="stat-card success">
          <div className="stat-icon">✅</div>
          <div className="stat-content">
            <span className="stat-value">{stats.published}</span>
            <span className="stat-label">Pubblicate</span>
          </div>
        </div>
        <div className="stat-card warning">
          <div className="stat-icon">📝</div>
          <div className="stat-content">
            <span className="stat-value">{stats.draft}</span>
            <span className="stat-label">Bozze</span>
          </div>
        </div>
        <div className="stat-card important">
          <div className="stat-icon">⭐</div>
          <div className="stat-content">
            <span className="stat-value">{stats.important}</span>
            <span className="stat-label">Importanti</span>
          </div>
        </div>
      </div>

      {error && <div className="alert alert-error">{error}</div>}

      <div className="filters">
        <input
          type="text"
          placeholder="Cerca per titolo, categoria..."
          value={search}
          onChange={(e) => setSearch(e.target.value)}
          className="search-input"
        />

        <select
          value={filter}
          onChange={(e) => setFilter(e.target.value as any)}
          className="filter-select"
        >
          <option value="all">Tutte</option>
          <option value="published">Pubblicate</option>
          <option value="draft">Bozze</option>
        </select>

        <button onClick={loadNews} className="btn btn-secondary">
          🔄 Aggiorna
        </button>
      </div>

      <div className="news-list">
        {filteredNews.length === 0 ? (
          <div className="no-data">Nessuna news trovata</div>
        ) : (
          filteredNews.map((news) => (
            <div key={news._id} className={`news-card ${news.isPublished ? 'published' : 'draft'}`}>
              <div className="news-header">
                <div className="news-title-section">
                  <h3>{news.title}</h3>
                  {news.important && <span className="badge badge-important">⭐ Importante</span>}
                  <span className={`badge ${news.isPublished ? 'badge-success' : 'badge-warning'}`}>
                    {news.isPublished ? '✅ Pubblicata' : '📝 Bozza'}
                  </span>
                </div>
                <span className="news-category">{news.category}</span>
              </div>

              <div className="news-body">
                <p className="news-excerpt">{news.excerpt}</p>
                <div className="news-meta">
                  <span>📅 {new Date(news.date).toLocaleDateString('it-IT')}</span>
                  <span>✍️ {news.author}</span>
                </div>
              </div>

              <div className="news-actions">
                <button onClick={() => handleEdit(news)} className="btn btn-sm btn-primary">
                  ✏️ Modifica
                </button>
                <button 
                  onClick={() => handleTogglePublish(news)} 
                  className={`btn btn-sm ${news.isPublished ? 'btn-warning' : 'btn-success'}`}
                >
                  {news.isPublished ? '👁️ Nascondi' : '✅ Pubblica'}
                </button>
                <button onClick={() => handleDelete(news._id)} className="btn btn-sm btn-danger">
                  🗑️ Elimina
                </button>
              </div>
            </div>
          ))
        )}
      </div>

      {showForm && (
        <div className="modal-overlay" onClick={() => { setShowForm(false); setEditingNews(null); resetForm(); }}>
          <div className="modal-content large" onClick={(e) => e.stopPropagation()}>
            <div className="modal-header">
              <h2>{editingNews ? 'Modifica News' : 'Nuova News'}</h2>
              <button onClick={() => { setShowForm(false); setEditingNews(null); resetForm(); }} className="btn-close">×</button>
            </div>
            <form onSubmit={handleSubmit} className="modal-body">
              <div className="form-group">
                <label>Titolo *</label>
                <input
                  type="text"
                  value={formData.title}
                  onChange={(e) => setFormData({ ...formData, title: e.target.value })}
                  required
                  placeholder="Titolo della news"
                />
              </div>

              <div className="form-group">
                <label>Estratto (anteprima)</label>
                <textarea
                  value={formData.excerpt}
                  onChange={(e) => setFormData({ ...formData, excerpt: e.target.value })}
                  placeholder="Breve descrizione (max 200 caratteri)"
                  rows={2}
                  maxLength={200}
                />
              </div>

              <div className="form-group">
                <label>Contenuto *</label>
                <textarea
                  value={formData.content}
                  onChange={(e) => setFormData({ ...formData, content: e.target.value })}
                  required
                  placeholder="Contenuto completo della news"
                  rows={8}
                />
              </div>

              <div className="form-row">
                <div className="form-group">
                  <label>Categoria</label>
                  <select
                    value={formData.category}
                    onChange={(e) => setFormData({ ...formData, category: e.target.value })}
                  >
                    <option value="Generica">Generica</option>
                    <option value="Normative">Normative</option>
                    <option value="Assemblee">Assemblee</option>
                    <option value="Concorsi">Concorsi</option>
                    <option value="Eventi">Eventi</option>
                    <option value="Formazione">Formazione</option>
                  </select>
                </div>

                <div className="form-group">
                  <label>Autore</label>
                  <input
                    type="text"
                    value={formData.author}
                    onChange={(e) => setFormData({ ...formData, author: e.target.value })}
                  />
                </div>
              </div>

              <div className="form-checks">
                <label className="checkbox-label">
                  <input
                    type="checkbox"
                    checked={formData.important}
                    onChange={(e) => setFormData({ ...formData, important: e.target.checked })}
                  />
                  <span>⭐ News Importante</span>
                </label>

                <label className="checkbox-label">
                  <input
                    type="checkbox"
                    checked={formData.isPublished}
                    onChange={(e) => setFormData({ ...formData, isPublished: e.target.checked })}
                  />
                  <span>✅ Pubblica immediatamente</span>
                </label>
              </div>

              <div className="modal-footer">
                <button type="button" onClick={() => { setShowForm(false); setEditingNews(null); resetForm(); }} className="btn btn-secondary">
                  Annulla
                </button>
                <button type="submit" className="btn btn-primary">
                  {editingNews ? 'Aggiorna News' : 'Crea News'}
                </button>
              </div>
            </form>
          </div>
        </div>
      )}
    </div>
  );
};

export default AdminNews;
