// src/services/news.service.ts
// Servizio per gestione news e comunicazioni

import api, { PaginationInfo } from './api';

// ============================================
// INTERFACCE
// ============================================

export interface News {
  _id: string;
  title: string;
  excerpt: string;
  content: string;
  date: string;
  category: string;
  author: string;
  image?: string;
  important: boolean;
  isPublished: boolean;
  createdAt: string;
  updatedAt?: string;
}

export interface NewsFilters {
  category?: string;
  important?: boolean;
  search?: string;
  page?: number;
  limit?: number;
}

// ============================================
// SERVIZIO NEWS
// ============================================

const newsService = {
  /**
   * Ottieni lista news con filtri e paginazione
   */
  getNews: async (filters: NewsFilters = {}) => {
    const params = new URLSearchParams();
    
    if (filters.category) params.append('category', filters.category);
    if (filters.important) params.append('important', 'true');
    if (filters.search) params.append('search', filters.search);
    if (filters.page) params.append('page', filters.page.toString());
    if (filters.limit) params.append('limit', filters.limit.toString());

    const queryString = params.toString();
    const endpoint = `/news${queryString ? `?${queryString}` : ''}`;
    
    return api.get(endpoint, false);
  },

  /**
   * Ottieni dettaglio singola news
   */
  getNewsById: async (id: string) => {
    return api.get(`/news/${id}`, false);
  },

  /**
   * Ottieni ultime news (per dashboard/home)
   */
  getLatestNews: async (count: number = 5) => {
    return api.get(`/news/latest?count=${count}`, false);
  },

  /**
   * Ottieni lista categorie disponibili
   */
  getCategories: async () => {
    return api.get('/news/categories', false);
  },
};

export default newsService;