import React, { useState, useEffect } from 'react';
import { API_BASE_URL } from '../services/adminApi';
import axios from 'axios';
import '../styles/AdminTokens.css';

interface Token {
  token: string;
  orderNumber: string;
  architectName: string;
  email: string | null;
  used: boolean;
  createdAt: string;
  expiresAt: string;
  usedBy?: string;
  usedAt?: string;
}

const AdminTokens: React.FC = () => {
  const [tokens, setTokens] = useState<Token[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState('');
  const [filter, setFilter] = useState<'all' | 'used' | 'available'>('all');
  const [search, setSearch] = useState('');
  const [showGenerateForm, setShowGenerateForm] = useState(false);
  const [showBulkForm, setShowBulkForm] = useState(false);
  const [stats, setStats] = useState({ total: 0, used: 0, available: 0, expired: 0 });

  // Form singolo
  const [formData, setFormData] = useState({
    orderNumber: '',
    architectName: '',
    email: ''
  });

  // Form bulk
  const [bulkData, setBulkData] = useState({
    count: 10,
    prefix: 'ARCH'
  });

  useEffect(() => {
    loadTokens();
    loadStats();
  }, [filter]);

  const loadTokens = async () => {
    try {
      setLoading(true);
      const token = localStorage.getItem('adminToken');
      
      const params: any = {};
      if (filter !== 'all') {
        params.status = filter;
      }

      const response = await axios.get(`${API_BASE_URL}/tokens`, {
        headers: { Authorization: `Bearer ${token}` },
        params
      });

      setTokens(response.data.data || []);
      setError('');
    } catch (err: any) {
      console.error('Errore caricamento token:', err);
      setError(err.response?.data?.message || 'Errore nel caricamento');
    } finally {
      setLoading(false);
    }
  };

  const loadStats = async () => {
    try {
      const token = localStorage.getItem('adminToken');
      const response = await axios.get(`${API_BASE_URL}/tokens/stats`, {
        headers: { Authorization: `Bearer ${token}` }
      });
      setStats(response.data.stats);
    } catch (err) {
      console.error('Errore caricamento statistiche:', err);
    }
  };

  const handleGenerateSingle = async (e: React.FormEvent) => {
    e.preventDefault();

    if (!formData.orderNumber || !formData.architectName) {
      alert('⚠️ Numero ordine e nome architetto richiesti');
      return;
    }

    try {
      const token = localStorage.getItem('adminToken');
      await axios.post(
        `${API_BASE_URL}/tokens/generate`,
        formData,
        { headers: { Authorization: `Bearer ${token}` } }
      );

      alert('✅ Token generato con successo!');
      setShowGenerateForm(false);
      setFormData({ orderNumber: '', architectName: '', email: '' });
      loadTokens();
      loadStats();
    } catch (err: any) {
      alert(err.response?.data?.message || 'Errore nella generazione');
    }
  };

  const handleGenerateBulk = async (e: React.FormEvent) => {
    e.preventDefault();

    if (bulkData.count < 1 || bulkData.count > 100) {
      alert('⚠️ Inserire un numero tra 1 e 100');
      return;
    }

    try {
      const token = localStorage.getItem('adminToken');
      const response = await axios.post(
        `${API_BASE_URL}/tokens/generate-bulk`,
        bulkData,
        { headers: { Authorization: `Bearer ${token}` } }
      );

      alert(`✅ ${bulkData.count} token generati con successo!`);
      setShowBulkForm(false);
      setBulkData({ count: 10, prefix: 'ARCH' });
      loadTokens();
      loadStats();
    } catch (err: any) {
      alert(err.response?.data?.message || 'Errore nella generazione');
    }
  };

  const handleRevoke = async (tokenValue: string) => {
    if (!window.confirm('Sei sicuro di voler eliminare questo token?')) {
      return;
    }

    try {
      const token = localStorage.getItem('adminToken');
      await axios.delete(`${API_BASE_URL}/tokens/${tokenValue}`, {
        headers: { Authorization: `Bearer ${token}` }
      });

      alert('✅ Token eliminato');
      loadTokens();
      loadStats();
    } catch (err: any) {
      alert(err.response?.data?.message || 'Errore nell\'eliminazione');
    }
  };

  const handleCopyToken = (tokenValue: string) => {
    navigator.clipboard.writeText(tokenValue);
    alert('📋 Token copiato negli appunti!');
  };

  const filteredTokens = tokens.filter(token => {
    const searchLower = search.toLowerCase();
    return (
      token.token?.toLowerCase().includes(searchLower) ||
      token.orderNumber?.toLowerCase().includes(searchLower) ||
      token.architectName?.toLowerCase().includes(searchLower)
    );
  });

  if (loading) {
    return (
      <div className="admin-tokens">
        <div className="loading">Caricamento token...</div>
      </div>
    );
  }

  return (
    <div className="admin-tokens">
      <div className="page-header">
        <h1>🎫 Gestione Token Attivazione</h1>
        <div className="header-actions">
          <button onClick={() => setShowGenerateForm(true)} className="btn btn-primary">
            ➕ Genera Token
          </button>
          <button onClick={() => setShowBulkForm(true)} className="btn btn-secondary">
            📦 Genera Multipli
          </button>
        </div>
      </div>

      <div className="stats-grid">
        <div className="stat-card">
          <div className="stat-icon">📊</div>
          <div className="stat-content">
            <span className="stat-value">{stats.total}</span>
            <span className="stat-label">Totale</span>
          </div>
        </div>
        <div className="stat-card success">
          <div className="stat-icon">✅</div>
          <div className="stat-content">
            <span className="stat-value">{stats.used}</span>
            <span className="stat-label">Utilizzati</span>
          </div>
        </div>
        <div className="stat-card primary">
          <div className="stat-icon">🎫</div>
          <div className="stat-content">
            <span className="stat-value">{stats.available}</span>
            <span className="stat-label">Disponibili</span>
          </div>
        </div>
        <div className="stat-card warning">
          <div className="stat-icon">⏰</div>
          <div className="stat-content">
            <span className="stat-value">{stats.expired}</span>
            <span className="stat-label">Scaduti</span>
          </div>
        </div>
      </div>

      {error && <div className="alert alert-error">{error}</div>}

      <div className="filters">
        <input
          type="text"
          placeholder="Cerca per token, numero ordine o nome..."
          value={search}
          onChange={(e) => setSearch(e.target.value)}
          className="search-input"
        />

        <select
          value={filter}
          onChange={(e) => setFilter(e.target.value as any)}
          className="filter-select"
        >
          <option value="all">Tutti</option>
          <option value="available">Disponibili</option>
          <option value="used">Utilizzati</option>
        </select>

        <button onClick={loadTokens} className="btn btn-secondary">
          🔄 Aggiorna
        </button>
      </div>

      <div className="tokens-list">
        {filteredTokens.length === 0 ? (
          <div className="no-data">Nessun token trovato</div>
        ) : (
          filteredTokens.map((token) => (
            <div key={token.token} className={`token-card ${token.used ? 'used' : 'available'}`}>
              <div className="token-header">
                <div className="token-value">
                  <code>{token.token}</code>
                  <button
                    onClick={() => handleCopyToken(token.token)}
                    className="btn-copy"
                    title="Copia token"
                  >
                    📋
                  </button>
                </div>
                <span className={`badge ${token.used ? 'badge-success' : 'badge-primary'}`}>
                  {token.used ? '✅ Utilizzato' : '🎫 Disponibile'}
                </span>
              </div>

              <div className="token-body">
                <div className="token-info">
                  <div className="info-item">
                    <strong>Numero Ordine:</strong>
                    <span>{token.orderNumber || '-'}</span>
                  </div>
                  <div className="info-item">
                    <strong>Architetto:</strong>
                    <span>{token.architectName}</span>
                  </div>
                  {token.email && (
                    <div className="info-item">
                      <strong>Email:</strong>
                      <span>{token.email}</span>
                    </div>
                  )}
                  <div className="info-item">
                    <strong>Creato il:</strong>
                    <span>{new Date(token.createdAt).toLocaleDateString('it-IT')}</span>
                  </div>
                  <div className="info-item">
                    <strong>Scade il:</strong>
                    <span>{new Date(token.expiresAt).toLocaleDateString('it-IT')}</span>
                  </div>
                  {token.used && token.usedAt && (
                    <div className="info-item">
                      <strong>Utilizzato il:</strong>
                      <span>{new Date(token.usedAt).toLocaleDateString('it-IT')}</span>
                    </div>
                  )}
                </div>
              </div>

              <div className="token-actions">
                {!token.used && (
                  <button
                    onClick={() => handleRevoke(token.token)}
                    className="btn btn-sm btn-danger"
                  >
                    🗑️ Elimina
                  </button>
                )}
              </div>
            </div>
          ))
        )}
      </div>

      {showGenerateForm && (
        <div className="modal-overlay" onClick={() => setShowGenerateForm(false)}>
          <div className="modal-content" onClick={(e) => e.stopPropagation()}>
            <div className="modal-header">
              <h2>Genera Nuovo Token</h2>
              <button onClick={() => setShowGenerateForm(false)} className="btn-close">×</button>
            </div>
            <form onSubmit={handleGenerateSingle} className="modal-body">
              <div className="form-group">
                <label>Numero Ordine *</label>
                <input
                  type="text"
                  value={formData.orderNumber}
                  onChange={(e) => setFormData({ ...formData, orderNumber: e.target.value })}
                  placeholder="es. 1234"
                  required
                />
              </div>
              <div className="form-group">
                <label>Nome Architetto *</label>
                <input
                  type="text"
                  value={formData.architectName}
                  onChange={(e) => setFormData({ ...formData, architectName: e.target.value })}
                  placeholder="es. Mario Rossi"
                  required
                />
              </div>
              <div className="form-group">
                <label>Email (opzionale)</label>
                <input
                  type="email"
                  value={formData.email}
                  onChange={(e) => setFormData({ ...formData, email: e.target.value })}
                  placeholder="es. mario.rossi@email.it"
                />
              </div>
              <div className="modal-footer">
                <button type="button" onClick={() => setShowGenerateForm(false)} className="btn btn-secondary">
                  Annulla
                </button>
                <button type="submit" className="btn btn-primary">
                  Genera Token
                </button>
              </div>
            </form>
          </div>
        </div>
      )}

      {showBulkForm && (
        <div className="modal-overlay" onClick={() => setShowBulkForm(false)}>
          <div className="modal-content" onClick={(e) => e.stopPropagation()}>
            <div className="modal-header">
              <h2>Genera Token in Blocco</h2>
              <button onClick={() => setShowBulkForm(false)} className="btn-close">×</button>
            </div>
            <form onSubmit={handleGenerateBulk} className="modal-body">
              <div className="form-group">
                <label>Quantità (1-100) *</label>
                <input
                  type="number"
                  min="1"
                  max="100"
                  value={bulkData.count}
                  onChange={(e) => setBulkData({ ...bulkData, count: parseInt(e.target.value) })}
                  required
                />
              </div>
              <div className="form-group">
                <label>Prefisso</label>
                <input
                  type="text"
                  value={bulkData.prefix}
                  onChange={(e) => setBulkData({ ...bulkData, prefix: e.target.value })}
                  placeholder="es. ARCH, BATCH, TOKEN"
                />
              </div>
              <div className="modal-footer">
                <button type="button" onClick={() => setShowBulkForm(false)} className="btn btn-secondary">
                  Annulla
                </button>
                <button type="submit" className="btn btn-primary">
                  Genera {bulkData.count} Token
                </button>
              </div>
            </form>
          </div>
        </div>
      )}
    </div>
  );
};

export default AdminTokens;
