// src/services/auth.service.ts
// Servizio per autenticazione e gestione utenti

import api, { setToken, removeToken } from './api';

// ============================================
// INTERFACCE
// ============================================

export interface User {
  _id: string;
  id?: string;
  email: string;
  firstName: string;
  lastName: string;
  phone?: string;
  userType: 'guest' | 'registered' | 'architect' | 'admin';
  isVerified: boolean;
  orderNumber?: string;
  language: string;
  settings?: UserSettings;
  architect?: ArchitectProfile;
  createdAt?: string;
  lastLogin?: string;
}

export interface UserSettings {
  notifications: boolean;
  emailNotifications: boolean;
  theme: string;
  language: string;
  privacy: {
    showEmail: boolean;
    showPhone: boolean;
    showProjects: boolean;
  };
}

export interface ArchitectProfile {
  _id: string;
  userId: string;
  orderNumber: string;
  specialties: string[];
  location: string;
  bio: string;
  profileVisible: boolean;
  acceptMessages: boolean;
  isAvailable: boolean;
  cfpCredits: number;
  projects: number;
  rating: number | null;
  services: string[];
  portfolio: any[];
  certifications: string[];
}

export interface LoginCredentials {
  email: string;
  password: string;
}

export interface RegisterData {
  email: string;
  password: string;
  firstName: string;
  lastName: string;
  phone?: string;
}

export interface ActivationData {
  activationToken: string;
  orderNumber: string;
}

export interface AuthResponse {
  success: boolean;
  message: string;
  token: string;
  user: User;
}

// ============================================
// SERVIZIO AUTH
// ============================================

const authService = {
  /**
   * Login utente
   */
  login: async (credentials: LoginCredentials): Promise<AuthResponse> => {
    const response = await api.post<AuthResponse>('/auth/login', credentials, false);
    if (response.success && response.token) {
      setToken(response.token);
      localStorage.setItem('user', JSON.stringify(response.user));
    }
    return response as AuthResponse;
  },

  /**
   * Registrazione nuovo utente
   */
  register: async (data: RegisterData): Promise<AuthResponse> => {
    const response = await api.post<AuthResponse>('/auth/register', data, false);
    if (response.success && response.token) {
      setToken(response.token);
      localStorage.setItem('user', JSON.stringify(response.user));
    }
    return response as AuthResponse;
  },

  /**
   * Accesso come ospite
   */
  guestAccess: async (): Promise<AuthResponse> => {
    const response = await api.post<AuthResponse>('/auth/guest', {}, false);
    if (response.success && response.token) {
      setToken(response.token);
      localStorage.setItem('user', JSON.stringify(response.user));
    }
    return response as AuthResponse;
  },

  /**
   * Logout - rimuove token e dati utente
   */
  logout: (): void => {
    removeToken();
    localStorage.removeItem('user');
  },

  /**
   * Ottieni dati utente corrente dal server
   */
  getCurrentUser: async (): Promise<User> => {
    const response = await api.get<{ user: User }>('/auth/me');
    if (response.success && response.user) {
      localStorage.setItem('user', JSON.stringify(response.user));
      return response.user;
    }
    throw new Error('Utente non trovato');
  },

  /**
   * Ottieni utente dalla cache locale (localStorage)
   */
  getCachedUser: (): User | null => {
    const userStr = localStorage.getItem('user');
    if (userStr) {
      try {
        return JSON.parse(userStr);
      } catch {
        return null;
      }
    }
    return null;
  },

  /**
   * Attiva profilo architetto con token
   */
  activateArchitect: async (data: ActivationData): Promise<AuthResponse> => {
    const response = await api.post<AuthResponse>('/auth/activate-architect', data);
    if (response.success && response.token) {
      setToken(response.token);
      localStorage.setItem('user', JSON.stringify(response.user));
    }
    return response as AuthResponse;
  },

 /**
   * Rinnova token JWT
   */
  refreshToken: async () => {
    const response = await api.post('/auth/refresh');
    if (response.success && response.token) {
      setToken(response.token);
    }
    return response;
  },

  /**
   * Cambio password
   */
  changePassword: async (currentPassword: string, newPassword: string) => {
    return api.post('/auth/change-password', { currentPassword, newPassword });
  },

  /**
   * Aggiorna profilo utente
   */
  updateProfile: async (userId: string, data: Partial<User>) => {
    return api.put(`/users/${userId}`, data);
  },

  /**
   * Aggiorna impostazioni utente
   */
  updateSettings: async (userId: string, settings: Partial<UserSettings>) => {
    return api.put(`/users/${userId}/settings`, { settings });
  },

  // ============================================
  // METODI DI UTILITÀ
  // ============================================

  /**
   * Verifica se l'utente è autenticato
   */
  isAuthenticated: (): boolean => {
    return !!localStorage.getItem('token');
  },

  /**
   * Verifica se è un utente guest
   */
  isGuest: (): boolean => {
    const user = authService.getCachedUser();
    return user?.userType === 'guest';
  },

  /**
   * Verifica se è un architetto verificato
   */
  isArchitect: (): boolean => {
    const user = authService.getCachedUser();
    return user?.userType === 'architect' && user?.isVerified === true;
  },

  /**
   * Verifica se è un admin
   */
  isAdmin: (): boolean => {
    const user = authService.getCachedUser();
    return user?.userType === 'admin';
  },

  /**
   * Ottieni il tipo di utente
   */
  getUserType: (): string | null => {
    const user = authService.getCachedUser();
    return user?.userType || null;
  },
};

export default authService;