// src/services/api.ts
// Client API centralizzato per comunicazione con il backend

const API_BASE_URL = process.env.REACT_APP_API_URL || 'http://localhost:5000/api';

// Interfaccia per le risposte API standard
export interface ApiResponse<T = any> {
  success: boolean;
  message?: string;
  error?: string;
  data?: T;
  [key: string]: any;
}

// Interfaccia per la paginazione
export interface PaginationInfo {
  currentPage: number;
  totalPages: number;
  totalItems: number;
  itemsPerPage: number;
  hasNextPage: boolean;
  hasPrevPage: boolean;
}

// ============================================
// GESTIONE TOKEN
// ============================================

export const getToken = (): string | null => {
  return localStorage.getItem('token');
};

export const setToken = (token: string): void => {
  localStorage.setItem('token', token);
};

export const removeToken = (): void => {
  localStorage.removeItem('token');
};

export const isAuthenticated = (): boolean => {
  return !!getToken();
};

// ============================================
// HEADERS
// ============================================

const getHeaders = (includeAuth: boolean = true): HeadersInit => {
  const headers: HeadersInit = {
    'Content-Type': 'application/json',
  };

  if (includeAuth) {
    const token = getToken();
    if (token) {
      headers['Authorization'] = `Bearer ${token}`;
    }
  }

  return headers;
};

// ============================================
// GESTIONE RISPOSTE
// ============================================

const handleResponse = async <T>(response: Response): Promise<ApiResponse<T>> => {
  let data: any;
  
  try {
    data = await response.json();
  } catch (error) {
    throw new Error('Errore nella risposta del server');
  }

  if (!response.ok) {
    // Se token scaduto o non valido
    if (response.status === 401) {
      removeToken();
      localStorage.removeItem('user');
      // Emetti evento per notificare logout forzato
      window.dispatchEvent(new CustomEvent('auth:logout'));
    }
    
    throw new Error(data.message || data.error || `Errore ${response.status}`);
  }

  return data;
};

// ============================================
// METODI HTTP
// ============================================

export const api = {
  /**
   * GET request
   * @param endpoint - Endpoint API (es: /news)
   * @param auth - Se includere token di autorizzazione (default: true)
   */
  get: async <T = any>(endpoint: string, auth: boolean = true): Promise<ApiResponse<T>> => {
    try {
      const response = await fetch(`${API_BASE_URL}${endpoint}`, {
        method: 'GET',
        headers: getHeaders(auth),
      });
      return handleResponse<T>(response);
    } catch (error) {
      if (error instanceof Error) {
        throw error;
      }
      throw new Error('Errore di connessione al server');
    }
  },

  /**
   * POST request
   * @param endpoint - Endpoint API
   * @param body - Body della richiesta
   * @param auth - Se includere token di autorizzazione (default: true)
   */
  post: async <T = any>(endpoint: string, body?: any, auth: boolean = true): Promise<ApiResponse<T>> => {
    try {
      const response = await fetch(`${API_BASE_URL}${endpoint}`, {
        method: 'POST',
        headers: getHeaders(auth),
        body: body ? JSON.stringify(body) : undefined,
      });
      return handleResponse<T>(response);
    } catch (error) {
      if (error instanceof Error) {
        throw error;
      }
      throw new Error('Errore di connessione al server');
    }
  },

  /**
   * PUT request
   * @param endpoint - Endpoint API
   * @param body - Body della richiesta
   * @param auth - Se includere token di autorizzazione (default: true)
   */
  put: async <T = any>(endpoint: string, body?: any, auth: boolean = true): Promise<ApiResponse<T>> => {
    try {
      const response = await fetch(`${API_BASE_URL}${endpoint}`, {
        method: 'PUT',
        headers: getHeaders(auth),
        body: body ? JSON.stringify(body) : undefined,
      });
      return handleResponse<T>(response);
    } catch (error) {
      if (error instanceof Error) {
        throw error;
      }
      throw new Error('Errore di connessione al server');
    }
  },

  /**
   * PATCH request
   * @param endpoint - Endpoint API
   * @param body - Corpo della richiesta
   * @param auth - Se includere token di autorizzazione (default: true)
   */
  patch: async <T = any>(endpoint: string, body?: any, auth: boolean = true): Promise<ApiResponse<T>> => {
    try {
      const response = await fetch(`${API_BASE_URL}${endpoint}`, {
        method: 'PATCH',
        headers: getHeaders(auth),
        body: body !== undefined ? JSON.stringify(body) : undefined,
      });
      return handleResponse<T>(response);
    } catch (error) {
      if (error instanceof Error) {
        throw error;
      }
      throw new Error('Errore di connessione al server');
    }
  },

  /**
   * DELETE request
   * @param endpoint - Endpoint API
   * @param auth - Se includere token di autorizzazione (default: true)
   */
  delete: async <T = any>(endpoint: string, auth: boolean = true): Promise<ApiResponse<T>> => {
    try {
      const response = await fetch(`${API_BASE_URL}${endpoint}`, {
        method: 'DELETE',
        headers: getHeaders(auth),
      });
      return handleResponse<T>(response);
    } catch (error) {
      if (error instanceof Error) {
        throw error;
      }
      throw new Error('Errore di connessione al server');
    }
  },
};

export default api;