// src/services/courses.service.ts
// Servizio per gestione corsi CFP

import api from './api';

// ============================================
// INTERFACCE
// ============================================

export interface Course {
  _id: string;
  title: string;
  description: string;
  date: string;
  cfpCredits: number;
  price: number;
  seatsAvailable: number;
  totalSeats: number;
  instructor: string;
  location: string;
  online: boolean;
  status: 'draft' | 'scheduled' | 'ongoing' | 'completed' | 'cancelled';
  category?: string;
  createdAt: string;
  updatedAt?: string;
  isEnrolled?: boolean;
}

export interface Enrollment {
  _id: string;
  courseId: string;
  userId: string;
  status: 'pending' | 'confirmed' | 'attended' | 'cancelled';
  paymentStatus: 'pending' | 'paid' | 'refunded';
  enrolledAt: string;
  cancelledAt?: string;
  course?: Course;
}

export interface CourseFilters {
  status?: string;
  online?: boolean;
  category?: string;
  upcoming?: boolean;
  page?: number;
  limit?: number;
}

// ============================================
// SERVIZIO CORSI
// ============================================

const coursesService = {
  /**
   * Ottieni lista corsi con filtri e paginazione
   */
  getCourses: async (filters: CourseFilters = {}) => {
    const params = new URLSearchParams();
    
    if (filters.status) params.append('status', filters.status);
    if (filters.online !== undefined) params.append('online', filters.online.toString());
    if (filters.category) params.append('category', filters.category);
    if (filters.upcoming) params.append('upcoming', 'true');
    if (filters.page) params.append('page', filters.page.toString());
    if (filters.limit) params.append('limit', filters.limit.toString());

    const queryString = params.toString();
    const endpoint = `/courses${queryString ? `?${queryString}` : ''}`;
    
    return api.get(endpoint, false);
  },

  /**
   * Ottieni dettaglio corso
   */
  getCourseById: async (id: string) => {
    return api.get(`/courses/${id}`);
  },

  /**
   * Iscrizione a un corso
   */
  enrollCourse: async (courseId: string) => {
    return api.post(`/courses/${courseId}/enroll`);
  },

  /**
   * Cancella iscrizione a un corso
   */
  cancelEnrollment: async (courseId: string) => {
    return api.delete(`/courses/${courseId}/enroll`);
  },

  /**
   * Ottieni le mie iscrizioni
   */
  getMyEnrollments: async () => {
    return api.get('/courses/my-enrollments');
  },
};

export default coursesService;