// src/services/architects.service.ts
// Servizio per gestione architetti e albo professionale

import api from './api';

// ============================================
// INTERFACCE
// ============================================

export interface Architect {
  _id: string;
  userId: string;
  orderNumber: string;
  specialties: string[];
  location: string;
  bio: string;
  profileVisible: boolean;
  acceptMessages: boolean;
  isAvailable: boolean;
  cfpCredits: number;
  projects: number;
  rating: number | null;
  services: string[];
  portfolio: PortfolioItem[];
  certifications: string[];
  createdAt?: string;
  updatedAt?: string;
  // Dati utente associati
  firstName?: string;
  lastName?: string;
  email?: string;
  phone?: string;
}

export interface PortfolioItem {
  title: string;
  year: number;
  type: string;
  image: string;
  description?: string;
}

export interface ArchitectFilters {
  search?: string;
  specialty?: string;
  location?: string;
  available?: boolean;
  page?: number;
  limit?: number;
}

export interface ArchitectProfileUpdate {
  specialties?: string[];
  location?: string;
  bio?: string;
  profileVisible?: boolean;
  acceptMessages?: boolean;
  isAvailable?: boolean;
  services?: string[];
  certifications?: string[];
}

// ============================================
// SERVIZIO ARCHITETTI
// ============================================

const architectsService = {
  /**
   * Ottieni lista architetti (albo professionale)
   */
  getArchitects: async (filters: ArchitectFilters = {}) => {
    const params = new URLSearchParams();
    
    if (filters.search) params.append('search', filters.search);
    if (filters.specialty) params.append('specialty', filters.specialty);
    if (filters.location) params.append('location', filters.location);
    if (filters.available) params.append('available', 'true');
    if (filters.page) params.append('page', filters.page.toString());
    if (filters.limit) params.append('limit', filters.limit.toString());

    const queryString = params.toString();
    const endpoint = `/architects${queryString ? `?${queryString}` : ''}`;
    
    return api.get(endpoint, false);
  },

  /**
   * Ottieni dettaglio architetto per ID
   */
  getArchitectById: async (id: string) => {
    return api.get(`/architects/${id}`, false);
  },

  /**
   * Aggiorna il proprio profilo architetto
   */
  updateMyProfile: async (data: ArchitectProfileUpdate) => {
    return api.put('/architects/me', data);
  },

  /**
   * Ottieni lista specializzazioni disponibili
   */
  getSpecialties: async () => {
    return api.get('/architects/specialties', false);
  },

  /**
   * Ottieni statistiche architetti
   */
  getStats: async () => {
    return api.get('/architects/stats', false);
  },
};

export default architectsService;