// frontend/src/services/users.service.ts
import api from './api';

export const usersService = {
  // Ottiene profilo utente
  getUserById: async (userId: string) => {
    return api.get(`/users/${userId}`);
  },

  // Aggiorna profilo utente
  updateUser: async (userId: string, updates: {
    firstName?: string;
    lastName?: string;
    phone?: string;
    bio?: string;
    language?: string;
  }) => {
    return api.put(`/users/${userId}`, updates);
  },

  // Aggiorna impostazioni
  updateSettings: async (userId: string, settings: any) => {
    return api.put(`/users/${userId}/settings`, { settings });
  },

  // Disattiva account
  deleteUser: async (userId: string) => {
    return api.delete(`/users/${userId}`);
  }
};
