import React from 'react';
import { Link, useLocation } from 'react-router-dom';
import '../styles/Sidebar.css';

const Sidebar: React.FC = () => {
  const location = useLocation();

  const isActive = (path: string) => {
    return location.pathname === path ? 'active' : '';
  };

  return (
    <div className="admin-sidebar">
      <div className="sidebar-header">
        <h2>Admin Panel</h2>
      </div>

      <nav className="sidebar-nav">
        <Link to="/admin/dashboard" className={isActive('/admin/dashboard')}>
          📊 Dashboard
        </Link>

        <Link to="/admin/users" className={isActive('/admin/users')}>
          👥 Utenti
        </Link>

        <Link to="/admin/architects" className={isActive('/admin/architects')}>
          🏛️ Architetti
        </Link>

        <Link 
          to="/admin/architects/pending" 
          className={isActive('/admin/architects/pending')}
          style={{ paddingLeft: '40px', fontSize: '14px' }}
        >
          ⏳ Richieste Pendenti
        </Link>

        <Link to="/admin/tokens" className={isActive('/admin/tokens')}>
          🎫 Token
        </Link>

        <Link to="/admin/news" className={isActive('/admin/news')}>
          📰 News
        </Link>

        <Link to="/admin/courses" className={isActive('/admin/courses')}>
          📚 Corsi
        </Link>

        <Link to="/admin/statistics" className={isActive('/admin/statistics')}>
          📈 Statistiche
        </Link>
      </nav>

      <div className="sidebar-footer">
        <button 
          onClick={() => {
            localStorage.removeItem('adminToken');
            window.location.href = '/admin/login';
          }}
          className="logout-btn"
        >
          🚪 Logout
        </button>
      </div>
    </div>
  );
};

export default Sidebar;