import React, { useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import { adminAuthService } from '../services/adminApi';

const AdminDashboard: React.FC = () => {
  const navigate = useNavigate();
  const user = adminAuthService.getUser();

  useEffect(() => {
    if (!adminAuthService.isAuthenticated()) {
      navigate('/admin/login');
    }
  }, [navigate]);

  const handleLogout = () => {
    adminAuthService.logout();
    navigate('/admin/login');
  };

  return (
    <div style={styles.container}>
      <header style={styles.header}>
        <div>
          <h1 style={styles.title}>🏛️ Pannello Admin</h1>
          <p style={styles.subtitle}>Ordine Architetti Caltanissetta</p>
        </div>
        <button onClick={handleLogout} style={styles.logoutBtn}>
          🚪 Logout
        </button>
      </header>

      <div style={styles.welcome}>
        <h2>Benvenuto, {user?.firstName}!</h2>
        <p>📧 {user?.email} | 👤 {user?.role}</p>
      </div>

      <div style={styles.grid}>
        <div style={styles.card}>
          <div style={styles.cardIcon}>👥</div>
          <h3 style={styles.cardTitle}>Utenti</h3>
          <p style={styles.cardText}>Gestione utenti sistema</p>
          <button onClick={() => navigate('/admin/users')} style={styles.cardButton}>Vai →</button>
        </div>

        <div style={styles.card}>
          <div style={styles.cardIcon}>🏛️</div>
          <h3 style={styles.cardTitle}>Architetti</h3>
          <p style={styles.cardText}>Approvazioni e gestione</p>
          <button onClick={() => navigate('/admin/architects')} style={styles.cardButton}>Vai →</button>
        </div>

        <div style={styles.card}>
          <div style={styles.cardIcon}>🔑</div>
          <h3 style={styles.cardTitle}>Token</h3>
          <p style={styles.cardText}>Generazione token attivazione</p>
          <button onClick={() => navigate('/admin/tokens')} style={styles.cardButton}>Vai →</button>
        </div>

        <div style={styles.card}>
          <div style={styles.cardIcon}>📰</div>
          <h3 style={styles.cardTitle}>News</h3>
          <p style={styles.cardText}>Gestione news e comunicazioni</p>
          <button onClick={() => navigate('/admin/news')} style={styles.cardButton}>Vai →</button>
        </div>

        <div style={styles.card}>
          <div style={styles.cardIcon}>🎓</div>
          <h3 style={styles.cardTitle}>Corsi</h3>
          <p style={styles.cardText}>Gestione corsi CFP</p>
          <button onClick={() => navigate('/admin/courses')} style={styles.cardButton}>Vai →</button>
        </div>

        <div style={styles.card}>
          <div style={styles.cardIcon}>📊</div>
          <h3 style={styles.cardTitle}>Statistiche</h3>
          <p style={styles.cardText}>Dashboard e analytics</p>
          <button onClick={() => navigate('/admin/statistics')} style={styles.cardButton}>Vai →</button>
        </div>
      </div>
    </div>
  );
};

const styles = {
  container: {
    minHeight: '100vh',
    background: '#f5f5f5',
    padding: '20px',
  },
  header: {
    background: 'white',
    padding: '20px',
    borderRadius: '12px',
    marginBottom: '20px',
    display: 'flex',
    justifyContent: 'space-between',
    alignItems: 'center',
    boxShadow: '0 2px 8px rgba(0,0,0,0.1)',
  },
  title: {
    fontSize: '24px',
    margin: 0,
  },
  subtitle: {
    color: '#666',
    margin: '4px 0 0 0',
  },
  logoutBtn: {
    padding: '10px 20px',
    background: '#e74c3c',
    color: 'white',
    border: 'none',
    borderRadius: '8px',
    cursor: 'pointer',
    fontSize: '14px',
    fontWeight: 'bold',
  },
  welcome: {
    background: 'linear-gradient(135deg, #667eea 0%, #764ba2 100%)',
    color: 'white',
    padding: '30px',
    borderRadius: '12px',
    marginBottom: '30px',
    textAlign: 'center' as const,
  },
  grid: {
    display: 'grid',
    gridTemplateColumns: 'repeat(auto-fit, minmax(280px, 1fr))',
    gap: '20px',
  },
  card: {
    background: 'white',
    padding: '24px',
    borderRadius: '12px',
    boxShadow: '0 2px 8px rgba(0,0,0,0.1)',
    textAlign: 'center' as const,
  },
  cardIcon: {
    fontSize: '48px',
    marginBottom: '12px',
  },
  cardTitle: {
    fontSize: '20px',
    marginBottom: '8px',
  },
  cardText: {
    color: '#666',
    marginBottom: '16px',
  },
  cardButton: {
    padding: '10px 24px',
    background: '#667eea',
    color: 'white',
    border: 'none',
    borderRadius: '8px',
    cursor: 'pointer',
    fontWeight: 'bold',
  },
};

export default AdminDashboard;