import React from 'react';
import ReactDOM from 'react-dom/client';
import './index.css';
import Root from './App';
import reportWebVitals from './reportWebVitals';

// Disable zoom on mobile devices
document.addEventListener('gesturestart', function (e) {
  e.preventDefault();
});

// Prevent pull-to-refresh on mobile
document.body.addEventListener('touchstart', (e) => {
  if (e.touches.length === 1) {
    // Handle single touch
  }
}, { passive: true });

document.body.addEventListener('touchend', (e) => {
  if (e.touches.length === 0) {
    // Handle touch end
  }
}, { passive: true });

document.body.addEventListener('touchmove', (e) => {
  if (e.touches.length === 1) {
    // Handle single touch move
  }
}, { passive: true });

// Service Worker per PWA - cache asset statici, API sempre live (no cache)
if ('serviceWorker' in navigator) {
  window.addEventListener('load', () => {
    navigator.serviceWorker.register('/service-worker.js')
      .then((registration) => {
        console.log('🔧 Service Worker registrato:', registration.scope);

        // Controlla aggiornamenti
        registration.addEventListener('updatefound', () => {
          const newWorker = registration.installing;
          if (newWorker) {
            newWorker.addEventListener('statechange', () => {
              if (newWorker.state === 'installed' && navigator.serviceWorker.controller) {
                console.log('🔄 Nuova versione disponibile. Aggiorna la pagina.');
              }
            });
          }
        });
      })
      .catch((error) => {
        console.log('❌ Registrazione Service Worker fallita:', error);
      });
  });
}

// ─── PASSWORD GATE ────────────────────────────────────────────────────────────
const GATE_KEY = 'oa_access_v1';
const GATE_HASH = 'Architetti2026!';

const PasswordGate: React.FC<{ children: React.ReactNode }> = ({ children }) => {
  const [unlocked, setUnlocked] = React.useState(() => {
    try { return localStorage.getItem(GATE_KEY) === '1'; } catch { return false; }
  });
  const [input, setInput] = React.useState('');
  const [error, setError] = React.useState(false);

  const tryUnlock = () => {
    if (input === GATE_HASH) {
      try { localStorage.setItem(GATE_KEY, '1'); } catch {}
      setUnlocked(true);
    } else {
      setError(true);
      setInput('');
      setTimeout(() => setError(false), 1500);
    }
  };

  if (unlocked) return <>{children}</>;

  return (
    <div style={{
      display:'flex', flexDirection:'column', alignItems:'center', justifyContent:'center',
      minHeight:'100vh', background:'linear-gradient(135deg,#1e3a5f 0%,#2563eb 100%)',
      fontFamily:'-apple-system,BlinkMacSystemFont,"Segoe UI",Roboto,sans-serif', padding:'20px'
    }}>
      <div style={{
        background:'white', borderRadius:'24px', padding:'40px 36px', maxWidth:'360px', width:'100%',
        boxShadow:'0 20px 60px rgba(0,0,0,0.3)', textAlign:'center'
      }}>
        <div style={{fontSize:'52px', marginBottom:'8px'}}>🏛️</div>
        <h2 style={{margin:'0 0 4px', color:'#1e3a5f', fontSize:'20px', fontWeight:'700'}}>
          Ordine Architetti
        </h2>
        <p style={{margin:'0 0 28px', color:'#64748b', fontSize:'13px'}}>
          P.P.C. Caltanissetta
        </p>
        <input
          type="password"
          placeholder="Password di accesso"
          value={input}
          onChange={e => setInput(e.target.value)}
          onKeyDown={e => e.key === 'Enter' && tryUnlock()}
          autoFocus
          style={{
            width:'100%', padding:'14px 16px', border: error ? '2px solid #ef4444' : '2px solid #e2e8f0',
            borderRadius:'12px', fontSize:'15px', outline:'none', boxSizing:'border-box',
            transition:'border 0.2s', background: error ? '#fef2f2' : 'white',
            marginBottom:'12px'
          }}
        />
        {error && <p style={{color:'#ef4444', fontSize:'13px', margin:'-4px 0 12px', fontWeight:'500'}}>
          Password errata. Riprova.
        </p>}
        <button
          onClick={tryUnlock}
          style={{
            width:'100%', padding:'14px', background:'linear-gradient(135deg,#2563eb,#1d4ed8)',
            color:'white', border:'none', borderRadius:'12px', fontSize:'15px',
            fontWeight:'600', cursor:'pointer', letterSpacing:'0.3px'
          }}
        >
          Accedi →
        </button>
      </div>
    </div>
  );
};
// ──────────────────────────────────────────────────────────────────────────────

// Create React root
const root = ReactDOM.createRoot(
  document.getElementById('root') as HTMLElement
);

// Render app with error boundary
const AppWrapper: React.FC = () => {
  const [hasError, setHasError] = React.useState(false);

  const ErrorFallback = () => (
    <div style={{
      display: 'flex',
      flexDirection: 'column',
      alignItems: 'center',
      justifyContent: 'center',
      minHeight: '100vh',
      padding: '20px',
      textAlign: 'center',
      fontFamily: '-apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif'
    }}>
      <div style={{
        background: 'linear-gradient(135deg, #2563eb 0%, #1d4ed8 100%)',
        color: 'white',
        padding: '20px',
        borderRadius: '20px',
        marginBottom: '20px'
      }}>
        <h1>⚠️ Errore Applicazione</h1>
        <p>Si è verificato un errore imprevisto.</p>
      </div>
      <button 
        onClick={() => window.location.reload()} 
        style={{
          padding: '12px 24px',
          background: '#2563eb',
          color: 'white',
          border: 'none',
          borderRadius: '12px',
          cursor: 'pointer',
          fontSize: '16px',
          fontWeight: '600'
        }}
      >
        🔄 Ricarica Pagina
      </button>
    </div>
  );

  React.useEffect(() => {
    const handleError = (error: ErrorEvent) => {
      console.error('💥 Global error:', error);
      setHasError(true);
    };

    const handleUnhandledRejection = (event: PromiseRejectionEvent) => {
      console.error('💥 Unhandled promise rejection:', event.reason);
      setHasError(true);
    };

    window.addEventListener('error', handleError);
    window.addEventListener('unhandledrejection', handleUnhandledRejection);

    return () => {
      window.removeEventListener('error', handleError);
      window.removeEventListener('unhandledrejection', handleUnhandledRejection);
    };
  }, []);

  if (hasError) {
    return <ErrorFallback />;
  }

  return (
    <React.StrictMode>
  <Root />
</React.StrictMode>
  );
};

root.render(
  <PasswordGate>
    <AppWrapper />
  </PasswordGate>
);

// Performance monitoring
reportWebVitals((metric) => {
  // Log web vitals for monitoring
  console.log('📊 Web Vital:', metric);
  
  // You can send metrics to analytics service here
  // Example: analytics.track('Web Vital', metric);
});

// Global error handling
window.onerror = (message, source, lineno, colno, error) => {
  console.error('💥 Runtime Error:', {
    message,
    source,
    lineno,
    colno,
    error
  });
  return false;
};

window.addEventListener('unhandledrejection', (event) => {
  console.error('💥 Unhandled Promise Rejection:', event.reason);
  event.preventDefault();
});

