import React, { useState, useEffect } from 'react';
import { API_BASE_URL } from '../services/adminApi';
import axios from 'axios';
import '../styles/AdminCourses.css';

interface Course {
  _id: string;
  title: string;
  description: string;
  date: string;
  cfpCredits: number;
  price: number;
  seatsAvailable: number;
  totalSeats: number;
  instructor: string;
  location: string;
  online: boolean;
  status: 'scheduled' | 'completed' | 'cancelled';
  createdAt: string;
}

const AdminCourses: React.FC = () => {
  const [courses, setCourses] = useState<Course[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState('');
  const [filter, setFilter] = useState<'all' | 'scheduled' | 'completed' | 'cancelled'>('all');
  const [search, setSearch] = useState('');
  const [showForm, setShowForm] = useState(false);
  const [editingCourse, setEditingCourse] = useState<Course | null>(null);
  const [stats, setStats] = useState({ total: 0, scheduled: 0, completed: 0, cancelled: 0, totalCFP: 0 });

  const [formData, setFormData] = useState({
    title: '',
    description: '',
    date: '',
    cfpCredits: 0,
    price: 0,
    totalSeats: 0,
    instructor: '',
    location: '',
    online: false,
    status: 'scheduled' as 'scheduled' | 'completed' | 'cancelled'
  });

  useEffect(() => {
    loadCourses();
    loadStats();
  }, [filter]);

  const loadCourses = async () => {
    try {
      setLoading(true);
      const token = localStorage.getItem('adminToken');
      
      const params: any = {};
      if (filter !== 'all') params.status = filter;

      const response = await axios.get(`${API_BASE_URL}/courses`, {
        headers: { Authorization: `Bearer ${token}` },
        params
      });

      setCourses(response.data.data || []);
      setError('');
    } catch (err: any) {
      console.error('Errore caricamento corsi:', err);
      setError(err.response?.data?.message || 'Errore nel caricamento');
    } finally {
      setLoading(false);
    }
  };

  const loadStats = async () => {
    try {
      const token = localStorage.getItem('adminToken');
      const response = await axios.get(`${API_BASE_URL}/courses/stats`, {
        headers: { Authorization: `Bearer ${token}` }
      });
      setStats(response.data.stats);
    } catch (err) {
      console.error('Errore caricamento statistiche:', err);
    }
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();

    if (!formData.title || !formData.date || !formData.cfpCredits) {
      alert('⚠️ Titolo, data e crediti CFP richiesti');
      return;
    }

    try {
      const token = localStorage.getItem('adminToken');

      if (editingCourse) {
        await axios.put(
          `${API_BASE_URL}/courses/${editingCourse._id}`,
          formData,
          { headers: { Authorization: `Bearer ${token}` } }
        );
        alert('✅ Corso aggiornato con successo!');
      } else {
        await axios.post(
          `${API_BASE_URL}/courses`,
          formData,
          { headers: { Authorization: `Bearer ${token}` } }
        );
        alert('✅ Corso creato con successo!');
      }

      setShowForm(false);
      setEditingCourse(null);
      resetForm();
      loadCourses();
      loadStats();
    } catch (err: any) {
      alert(err.response?.data?.message || 'Errore nell\'operazione');
    }
  };

  const handleEdit = (course: Course) => {
    setEditingCourse(course);
    setFormData({
      title: course.title,
      description: course.description,
      date: course.date.split('T')[0],
      cfpCredits: course.cfpCredits,
      price: course.price,
      totalSeats: course.totalSeats,
      instructor: course.instructor,
      location: course.location,
      online: course.online,
      status: course.status
    });
    setShowForm(true);
  };

  const handleDelete = async (id: string) => {
    if (!window.confirm('Sei sicuro di voler eliminare questo corso?')) {
      return;
    }

    try {
      const token = localStorage.getItem('adminToken');
      await axios.delete(`${API_BASE_URL}/courses/${id}`, {
        headers: { Authorization: `Bearer ${token}` }
      });

      alert('✅ Corso eliminato');
      loadCourses();
      loadStats();
    } catch (err: any) {
      alert(err.response?.data?.message || 'Errore nell\'eliminazione');
    }
  };

  const resetForm = () => {
    setFormData({
      title: '',
      description: '',
      date: '',
      cfpCredits: 0,
      price: 0,
      totalSeats: 0,
      instructor: '',
      location: '',
      online: false,
      status: 'scheduled'
    });
  };

  const filteredCourses = courses.filter(course => {
    const searchLower = search.toLowerCase();
    return (
      course.title?.toLowerCase().includes(searchLower) ||
      course.instructor?.toLowerCase().includes(searchLower) ||
      course.location?.toLowerCase().includes(searchLower)
    );
  });

  const getStatusBadge = (status: string) => {
    switch(status) {
      case 'scheduled': return <span className="badge badge-primary">📅 Programmato</span>;
      case 'completed': return <span className="badge badge-success">✅ Completato</span>;
      case 'cancelled': return <span className="badge badge-danger">❌ Annullato</span>;
      default: return null;
    }
  };

  if (loading) {
    return (
      <div className="admin-courses">
        <div className="loading">Caricamento corsi...</div>
      </div>
    );
  }

  return (
    <div className="admin-courses">
      <div className="page-header">
        <h1>📚 Gestione Corsi CFP</h1>
        <button onClick={() => { setShowForm(true); setEditingCourse(null); resetForm(); }} className="btn btn-primary">
          ➕ Nuovo Corso
        </button>
      </div>

      <div className="stats-grid">
        <div className="stat-card">
          <div className="stat-icon">📊</div>
          <div className="stat-content">
            <span className="stat-value">{stats.total}</span>
            <span className="stat-label">Totale Corsi</span>
          </div>
        </div>
        <div className="stat-card primary">
          <div className="stat-icon">📅</div>
          <div className="stat-content">
            <span className="stat-value">{stats.scheduled}</span>
            <span className="stat-label">Programmati</span>
          </div>
        </div>
        <div className="stat-card success">
          <div className="stat-icon">✅</div>
          <div className="stat-content">
            <span className="stat-value">{stats.completed}</span>
            <span className="stat-label">Completati</span>
          </div>
        </div>
        <div className="stat-card cfp">
          <div className="stat-icon">🎓</div>
          <div className="stat-content">
            <span className="stat-value">{stats.totalCFP}</span>
            <span className="stat-label">Crediti CFP Tot</span>
          </div>
        </div>
      </div>

      {error && <div className="alert alert-error">{error}</div>}

      <div className="filters">
        <input
          type="text"
          placeholder="Cerca per titolo, docente o località..."
          value={search}
          onChange={(e) => setSearch(e.target.value)}
          className="search-input"
        />

        <select
          value={filter}
          onChange={(e) => setFilter(e.target.value as any)}
          className="filter-select"
        >
          <option value="all">Tutti</option>
          <option value="scheduled">Programmati</option>
          <option value="completed">Completati</option>
          <option value="cancelled">Annullati</option>
        </select>

        <button onClick={loadCourses} className="btn btn-secondary">
          🔄 Aggiorna
        </button>
      </div>

      <div className="courses-grid">
        {filteredCourses.length === 0 ? (
          <div className="no-data">Nessun corso trovato</div>
        ) : (
          filteredCourses.map((course) => (
            <div key={course._id} className={`course-card status-${course.status}`}>
              <div className="course-header">
                <h3>{course.title}</h3>
                {getStatusBadge(course.status)}
              </div>

              <div className="course-body">
                <p className="course-description">{course.description}</p>
                
                <div className="course-details">
                  <div className="detail-item">
                    <span className="icon">📅</span>
                    <span>{new Date(course.date).toLocaleDateString('it-IT')}</span>
                  </div>
                  <div className="detail-item">
                    <span className="icon">🎓</span>
                    <span>{course.cfpCredits} CFP</span>
                  </div>
                  <div className="detail-item">
                    <span className="icon">💰</span>
                    <span>{course.price}€</span>
                  </div>
                  <div className="detail-item">
                    <span className="icon">👥</span>
                    <span>{course.seatsAvailable}/{course.totalSeats} posti</span>
                  </div>
                  <div className="detail-item">
                    <span className="icon">👨‍🏫</span>
                    <span>{course.instructor}</span>
                  </div>
                  <div className="detail-item">
                    <span className="icon">{course.online ? '💻' : '📍'}</span>
                    <span>{course.location}</span>
                  </div>
                </div>
              </div>

              <div className="course-actions">
                <button onClick={() => handleEdit(course)} className="btn btn-sm btn-primary">
                  ✏️ Modifica
                </button>
                <button onClick={() => handleDelete(course._id)} className="btn btn-sm btn-danger">
                  🗑️ Elimina
                </button>
              </div>
            </div>
          ))
        )}
      </div>

      {showForm && (
        <div className="modal-overlay" onClick={() => { setShowForm(false); setEditingCourse(null); resetForm(); }}>
          <div className="modal-content large" onClick={(e) => e.stopPropagation()}>
            <div className="modal-header">
              <h2>{editingCourse ? 'Modifica Corso' : 'Nuovo Corso'}</h2>
              <button onClick={() => { setShowForm(false); setEditingCourse(null); resetForm(); }} className="btn-close">×</button>
            </div>
            <form onSubmit={handleSubmit} className="modal-body">
              <div className="form-group">
                <label>Titolo *</label>
                <input
                  type="text"
                  value={formData.title}
                  onChange={(e) => setFormData({ ...formData, title: e.target.value })}
                  required
                  placeholder="Titolo del corso"
                />
              </div>

              <div className="form-group">
                <label>Descrizione</label>
                <textarea
                  value={formData.description}
                  onChange={(e) => setFormData({ ...formData, description: e.target.value })}
                  placeholder="Descrizione del corso"
                  rows={3}
                />
              </div>

              <div className="form-row">
                <div className="form-group">
                  <label>Data *</label>
                  <input
                    type="date"
                    value={formData.date}
                    onChange={(e) => setFormData({ ...formData, date: e.target.value })}
                    required
                  />
                </div>

                <div className="form-group">
                  <label>Crediti CFP *</label>
                  <input
                    type="number"
                    value={formData.cfpCredits}
                    onChange={(e) => setFormData({ ...formData, cfpCredits: parseInt(e.target.value) || 0 })}
                    required
                    min="0"
                  />
                </div>
              </div>

              <div className="form-row">
                <div className="form-group">
                  <label>Prezzo (€)</label>
                  <input
                    type="number"
                    value={formData.price}
                    onChange={(e) => setFormData({ ...formData, price: parseFloat(e.target.value) || 0 })}
                    min="0"
                    step="0.01"
                  />
                </div>

                <div className="form-group">
                  <label>Posti Totali</label>
                  <input
                    type="number"
                    value={formData.totalSeats}
                    onChange={(e) => setFormData({ ...formData, totalSeats: parseInt(e.target.value) || 0 })}
                    min="0"
                  />
                </div>
              </div>

              <div className="form-group">
                <label>Docente</label>
                <input
                  type="text"
                  value={formData.instructor}
                  onChange={(e) => setFormData({ ...formData, instructor: e.target.value })}
                  placeholder="Nome del docente"
                />
              </div>

              <div className="form-row">
                <div className="form-group">
                  <label>Località</label>
                  <input
                    type="text"
                    value={formData.location}
                    onChange={(e) => setFormData({ ...formData, location: e.target.value })}
                    placeholder="Sede del corso"
                  />
                </div>

                <div className="form-group">
                  <label>Stato</label>
                  <select
                    value={formData.status}
                    onChange={(e) => setFormData({ ...formData, status: e.target.value as any })}
                  >
                    <option value="scheduled">Programmato</option>
                    <option value="completed">Completato</option>
                    <option value="cancelled">Annullato</option>
                  </select>
                </div>
              </div>

              <div className="form-checks">
                <label className="checkbox-label">
                  <input
                    type="checkbox"
                    checked={formData.online}
                    onChange={(e) => setFormData({ ...formData, online: e.target.checked })}
                  />
                  <span>💻 Corso Online</span>
                </label>
              </div>

              <div className="modal-footer">
                <button type="button" onClick={() => { setShowForm(false); setEditingCourse(null); resetForm(); }} className="btn btn-secondary">
                  Annulla
                </button>
                <button type="submit" className="btn btn-primary">
                  {editingCourse ? 'Aggiorna Corso' : 'Crea Corso'}
                </button>
              </div>
            </form>
          </div>
        </div>
      )}
    </div>
  );
};

export default AdminCourses;
