// frontend/src/admin/pages/AdminArchitects.tsx
import { API_BASE_URL } from '../services/adminApi';
import React, { useState, useEffect } from 'react';
import axios from 'axios';
import '../styles/AdminArchitects.css';

interface User {
  id: string;
  email: string;
  firstName: string;
  lastName: string;
  phone?: string;
  isActive: boolean;
  isVerified: boolean;
  createdAt: string;
  lastLogin?: string;
}

interface Architect {
  _id: string;
  userId: string;
  orderNumber: string;
  specialties: string[];
  location: string;
  bio: string;
  profileVisible: boolean;
  acceptMessages: boolean;
  isAvailable: boolean;
  cfpCredits: number;
  projects: number;
  rating: number | null;
  user: User;
}

const AdminArchitects: React.FC = () => {
  const [architects, setArchitects] = useState<Architect[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState('');
  const [search, setSearch] = useState('');
  const [statusFilter, setStatusFilter] = useState<'all' | 'active' | 'inactive' | 'pending'>('all');
  const [selectedArchitect, setSelectedArchitect] = useState<Architect | null>(null);

  useEffect(() => {
    loadArchitects();
  }, [statusFilter]);

  const loadArchitects = async () => {
    try {
      setLoading(true);
      const token = localStorage.getItem('adminToken');
      
      const params: any = {};
      if (statusFilter !== 'all') {
        params.status = statusFilter;
      }

      const response = await axios.get(`${API_BASE_URL}/architects`, {
        headers: { Authorization: `Bearer ${token}` },
        params
      });

      setArchitects(response.data.data || []);
      setError('');
    } catch (err: any) {
      console.error('Errore caricamento architetti:', err);
      setError(err.response?.data?.message || 'Errore nel caricamento');
    } finally {
      setLoading(false);
    }
  };

  const handleDelete = async (architectId: string) => {
    if (!window.confirm('Sei sicuro di voler eliminare questo architetto definitivamente?')) {
      return;
    }

    try {
      const token = localStorage.getItem('adminToken');
      await axios.delete(`${API_BASE_URL}/architects/${architectId}`, {
        headers: { Authorization: `Bearer ${token}` }
      });

      alert('Architetto eliminato con successo');
      loadArchitects();
    } catch (err: any) {
      alert(err.response?.data?.message || 'Errore nell\'eliminazione');
    }
  };

  const handleToggleActive = async (userId: string, isActive: boolean) => {
    try {
      const token = localStorage.getItem('adminToken');
      const endpoint = isActive 
        ? `${API_BASE_URL}/users/${userId}/deactivate`
        : `${API_BASE_URL}/users/${userId}/activate`;

      await axios.post(endpoint, {}, {
        headers: { Authorization: `Bearer ${token}` }
      });

      alert(`Architetto ${isActive ? 'disattivato' : 'attivato'} con successo`);
      loadArchitects();
    } catch (err: any) {
      alert(err.response?.data?.message || 'Errore nell\'operazione');
    }
  };

  const filteredArchitects = architects.filter(arch => {
    const searchLower = search.toLowerCase();
    return (
      arch.user?.firstName?.toLowerCase().includes(searchLower) ||
      arch.user?.lastName?.toLowerCase().includes(searchLower) ||
      arch.user?.email?.toLowerCase().includes(searchLower) ||
      arch.location?.toLowerCase().includes(searchLower)
    );
  });

  const getStatusBadge = (architect: Architect) => {
    if (!architect.user?.isVerified) {
      return <span className="badge badge-warning">In attesa</span>;
    }
    if (!architect.user?.isActive) {
      return <span className="badge badge-danger">Disattivato</span>;
    }
    return <span className="badge badge-success">Attivo</span>;
  };

  if (loading) {
    return (
      <div className="admin-architects">
        <div className="loading">Caricamento architetti...</div>
      </div>
    );
  }

  return (
    <div className="admin-architects">
      <div className="page-header">
        <h1>Gestione Architetti</h1>
        <div className="header-stats">
          <div className="stat-item">
            <span className="stat-value">{architects.length}</span>
            <span className="stat-label">Totale</span>
          </div>
          <div className="stat-item">
            <span className="stat-value">
              {architects.filter(a => a.user?.isActive && a.user?.isVerified).length}
            </span>
            <span className="stat-label">Attivi</span>
          </div>
          <div className="stat-item">
            <span className="stat-value">
              {architects.filter(a => !a.user?.isVerified).length}
            </span>
            <span className="stat-label">Pendenti</span>
          </div>
        </div>
      </div>

      {error && (
        <div className="alert alert-error">
          {error}
        </div>
      )}

      <div className="filters">
        <input
          type="text"
          placeholder="Cerca per nome, email o località..."
          value={search}
          onChange={(e) => setSearch(e.target.value)}
          className="search-input"
        />

        <select
          value={statusFilter}
          onChange={(e) => setStatusFilter(e.target.value as any)}
          className="filter-select"
        >
          <option value="all">Tutti</option>
          <option value="active">Attivi</option>
          <option value="inactive">Disattivati</option>
          <option value="pending">In attesa</option>
        </select>

        <button onClick={loadArchitects} className="btn btn-secondary">
          🔄 Aggiorna
        </button>
      </div>

      <div className="table-container">
        <table className="architects-table">
          <thead>
            <tr>
              <th>Nome</th>
              <th>Email</th>
              <th>Località</th>
              <th>Stato</th>
              <th>Iscrizione</th>
              <th>Azioni</th>
            </tr>
          </thead>
          <tbody>
            {filteredArchitects.length === 0 ? (
              <tr>
                <td colSpan={6} className="no-data">
                  Nessun architetto trovato
                </td>
              </tr>
            ) : (
              filteredArchitects.map((architect) => (
                <tr key={architect._id}>
                  <td>
                    <div className="user-info">
                      <strong>
                        {architect.user?.firstName} {architect.user?.lastName}
                      </strong>
                    </div>
                  </td>
                  <td>{architect.user?.email}</td>
                  <td>{architect.location || '-'}</td>
                  <td>{getStatusBadge(architect)}</td>
                  <td>
                    {architect.user?.createdAt
                      ? new Date(architect.user.createdAt).toLocaleDateString('it-IT')
                      : '-'}
                  </td>
                  <td>
                    <div className="actions">
                      <button
                        onClick={() => setSelectedArchitect(architect)}
                        className="btn btn-sm btn-primary"
                        title="Visualizza dettagli"
                      >
                        👁️
                      </button>
                      
                      {architect.user?.isActive ? (
                        <button
                          onClick={() => handleToggleActive(architect.user.id, true)}
                          className="btn btn-sm btn-warning"
                          title="Disattiva"
                        >
                          ⏸️
                        </button>
                      ) : (
                        <button
                          onClick={() => handleToggleActive(architect.user.id, false)}
                          className="btn btn-sm btn-success"
                          title="Attiva"
                        >
                          ▶️
                        </button>
                      )}

                      <button
                        onClick={() => handleDelete(architect._id)}
                        className="btn btn-sm btn-danger"
                        title="Elimina"
                      >
                        🗑️
                      </button>
                    </div>
                  </td>
                </tr>
              ))
            )}
          </tbody>
        </table>
      </div>

      {selectedArchitect && (
        <ArchitectDetailModal
          architect={selectedArchitect}
          onClose={() => setSelectedArchitect(null)}
          onUpdate={loadArchitects}
        />
      )}
    </div>
  );
};

const ArchitectDetailModal: React.FC<{
  architect: Architect;
  onClose: () => void;
  onUpdate: () => void;
}> = ({ architect, onClose, onUpdate }) => {
  return (
    <div className="modal-overlay" onClick={onClose}>
      <div className="modal-content" onClick={(e) => e.stopPropagation()}>
        <div className="modal-header">
          <h2>Dettagli Architetto</h2>
          <button onClick={onClose} className="btn-close">×</button>
        </div>
        
        <div className="modal-body">
          <div className="detail-section">
            <h3>Informazioni Personali</h3>
            <p><strong>Nome:</strong> {architect.user?.firstName} {architect.user?.lastName}</p>
            <p><strong>Email:</strong> {architect.user?.email}</p>
            <p><strong>Telefono:</strong> {architect.user?.phone || '-'}</p>
            <p><strong>Località:</strong> {architect.location}</p>
          </div>

          <div className="detail-section">
            <h3>Profilo Professionale</h3>
            <p><strong>Numero Ordine:</strong> {architect.orderNumber}</p>
            <p><strong>Bio:</strong> {architect.bio || 'Non disponibile'}</p>
            <p><strong>CFP:</strong> {architect.cfpCredits}</p>
            <p><strong>Progetti:</strong> {architect.projects}</p>
            <p><strong>Rating:</strong> {architect.rating || '-'}</p>
          </div>

          <div className="detail-section">
            <h3>Stato Account</h3>
            <p><strong>Attivo:</strong> {architect.user?.isActive ? '✅ Sì' : '❌ No'}</p>
            <p><strong>Verificato:</strong> {architect.user?.isVerified ? '✅ Sì' : '❌ No'}</p>
            <p><strong>Profilo Visibile:</strong> {architect.profileVisible ? '✅ Sì' : '❌ No'}</p>
            <p><strong>Accetta Messaggi:</strong> {architect.acceptMessages ? '✅ Sì' : '❌ No'}</p>
          </div>
        </div>

        <div className="modal-footer">
          <button onClick={onClose} className="btn btn-secondary">
            Chiudi
          </button>
        </div>
      </div>
    </div>
  );
};

export default AdminArchitects;
