import React, { useState, useEffect } from 'react';
import { API_BASE_URL } from '../services/adminApi';
import axios from 'axios';
import '../styles/AdminArchitectsPending.css';

interface User {
  id: string;
  email: string;
  firstName: string;
  lastName: string;
  phone?: string;
  createdAt: string;
}

interface PendingArchitect {
  _id: string;
  userId: string;
  orderNumber: string;
  location: string;
  bio: string;
  user: User;
}

const AdminArchitectsPending: React.FC = () => {
  const [pending, setPending] = useState<PendingArchitect[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState('');
  const [rejectReason, setRejectReason] = useState('');
  const [selectedArchitect, setSelectedArchitect] = useState<string | null>(null);

  useEffect(() => {
    loadPending();
  }, []);

  const loadPending = async () => {
    try {
      setLoading(true);
      const token = localStorage.getItem('adminToken');
      
      const response = await axios.get(`${API_BASE_URL}/architects/pending`, {
        headers: { Authorization: `Bearer ${token}` }
      });

      setPending(response.data.architects || []);
      setError('');
    } catch (err: any) {
      console.error('Errore caricamento pendenti:', err);
      setError(err.response?.data?.message || 'Errore nel caricamento');
    } finally {
      setLoading(false);
    }
  };

  const handleApprove = async (architectId: string, userName: string) => {
    if (!window.confirm(`Sei sicuro di voler APPROVARE ${userName}?`)) {
      return;
    }

    try {
      const token = localStorage.getItem('adminToken');
      await axios.post(
        `${API_BASE_URL}/architects/${architectId}/approve`,
        {},
        { headers: { Authorization: `Bearer ${token}` } }
      );

      alert('✅ Architetto approvato con successo!');
      loadPending();
    } catch (err: any) {
      alert(err.response?.data?.message || 'Errore nell\'approvazione');
    }
  };

  const handleReject = async (architectId: string) => {
    if (!rejectReason.trim()) {
      alert('⚠️ Inserisci un motivo per il rifiuto');
      return;
    }

    try {
      const token = localStorage.getItem('adminToken');
      await axios.post(
        `${API_BASE_URL}/architects/${architectId}/reject`,
        { reason: rejectReason },
        { headers: { Authorization: `Bearer ${token}` } }
      );

      alert('❌ Architetto rifiutato');
      setSelectedArchitect(null);
      setRejectReason('');
      loadPending();
    } catch (err: any) {
      alert(err.response?.data?.message || 'Errore nel rifiuto');
    }
  };

  if (loading) {
    return (
      <div className="admin-pending">
        <div className="loading">Caricamento richieste...</div>
      </div>
    );
  }

  return (
    <div className="admin-pending">
      <div className="page-header">
        <h1>⏳ Richieste in Attesa</h1>
        <div className="pending-count">
          <span className="count-value">{pending.length}</span>
          <span className="count-label">Richieste</span>
        </div>
      </div>

      {error && (
        <div className="alert alert-error">
          {error}
        </div>
      )}

      {pending.length === 0 ? (
        <div className="no-pending">
          <div className="no-pending-icon">✅</div>
          <h2>Nessuna richiesta in attesa</h2>
          <p>Tutte le richieste sono state processate!</p>
        </div>
      ) : (
        <div className="pending-list">
          {pending.map((architect) => (
            <div key={architect._id} className="pending-card">
              <div className="card-header">
                <div className="architect-info">
                  <h3>{architect.user?.firstName} {architect.user?.lastName}</h3>
                  <p className="email">📧 {architect.user?.email}</p>
                  {architect.user?.phone && (
                    <p className="phone">📱 {architect.user.phone}</p>
                  )}
                </div>
                <div className="request-date">
                  <span className="date-label">Richiesta il</span>
                  <span className="date-value">
                    {new Date(architect.user?.createdAt).toLocaleDateString('it-IT')}
                  </span>
                </div>
              </div>

              <div className="card-body">
                <div className="info-row">
                  <strong>Numero Ordine:</strong>
                  <span>{architect.orderNumber}</span>
                </div>
                <div className="info-row">
                  <strong>Località:</strong>
                  <span>{architect.location}</span>
                </div>
                {architect.bio && (
                  <div className="info-row bio">
                    <strong>Bio:</strong>
                    <p>{architect.bio}</p>
                  </div>
                )}
              </div>

              <div className="card-actions">
                <button
                  onClick={() => handleApprove(architect._id, `{architect.user?.firstName} {architect.user?.lastName}`)}
                  className="btn btn-approve"
                >
                  ✅ Approva
                </button>

                {selectedArchitect === architect._id ? (
                  <div className="reject-form">
                    <input
                      type="text"
                      placeholder="Motivo del rifiuto..."
                      value={rejectReason}
                      onChange={(e) => setRejectReason(e.target.value)}
                      className="reject-input"
                      autoFocus
                    />
                    <button
                      onClick={() => handleReject(architect._id)}
                      className="btn btn-reject-confirm"
                    >
                      Conferma Rifiuto
                    </button>
                    <button
                      onClick={() => {
                        setSelectedArchitect(null);
                        setRejectReason('');
                      }}
                      className="btn btn-cancel"
                    >
                      Annulla
                    </button>
                  </div>
                ) : (
                  <button
                    onClick={() => setSelectedArchitect(architect._id)}
                    className="btn btn-reject"
                  >
                    ❌ Rifiuta
                  </button>
                )}
              </div>
            </div>
          ))}
        </div>
      )}
    </div>
  );
};

export default AdminArchitectsPending;
