import React, { useState, useEffect } from 'react';
import { API_BASE_URL } from '../services/adminApi';
import axios from 'axios';
import '../styles/AdminStatistics.css';

interface Statistics {
  users: {
    total: number;
    active: number;
    verified: number;
    architects: number;
    citizens: number;
  };
  architects: {
    total: number;
    visible: number;
    acceptingMessages: number;
    available: number;
    totalCFP: number;
    totalProjects: number;
  };
  tokens: {
    total: number;
    used: number;
    available: number;
    expired: number;
  };
  news: {
    total: number;
    published: number;
    draft: number;
    important: number;
  };
  courses: {
    total: number;
    scheduled: number;
    completed: number;
    totalCFP: number;
    totalSeats: number;
    availableSeats: number;
  };
  monthlyRegistrations: Record<string, number>;
}

const AdminStatistics: React.FC = () => {
  const [stats, setStats] = useState<Statistics | null>(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState('');
  const [generatedAt, setGeneratedAt] = useState('');

  useEffect(() => {
    loadStatistics();
  }, []);

  const loadStatistics = async () => {
    try {
      setLoading(true);
      const token = localStorage.getItem('adminToken');
      
      const response = await axios.get(`${API_BASE_URL}/statistics`, {
        headers: { Authorization: `Bearer ${token}` }
      });

      setStats(response.data.statistics);
      setGeneratedAt(response.data.generatedAt);
      setError('');
    } catch (err: any) {
      console.error('Errore caricamento statistiche:', err);
      setError(err.response?.data?.message || 'Errore nel caricamento');
    } finally {
      setLoading(false);
    }
  };

  if (loading) {
    return (
      <div className="admin-statistics">
        <div className="loading">Caricamento statistiche...</div>
      </div>
    );
  }

  if (error || !stats) {
    return (
      <div className="admin-statistics">
        <div className="alert alert-error">{error || 'Nessun dato disponibile'}</div>
      </div>
    );
  }

  return (
    <div className="admin-statistics">
      <div className="page-header">
        <div>
          <h1>📊 Statistiche Sistema</h1>
          <p className="generated-at">
            Aggiornato: {new Date(generatedAt).toLocaleString('it-IT')}
          </p>
        </div>
        <button onClick={loadStatistics} className="btn btn-primary">
          🔄 Aggiorna
        </button>
      </div>

      <div className="stats-section">
        <h2>👥 Utenti</h2>
        <div className="stats-grid">
          <div className="stat-card large primary">
            <div className="stat-icon">👥</div>
            <div className="stat-content">
              <span className="stat-value">{stats.users.total}</span>
              <span className="stat-label">Utenti Totali</span>
            </div>
          </div>
          <div className="stat-card success">
            <div className="stat-icon">✅</div>
            <div className="stat-content">
              <span className="stat-value">{stats.users.active}</span>
              <span className="stat-label">Attivi</span>
            </div>
          </div>
          <div className="stat-card info">
            <div className="stat-icon">🔐</div>
            <div className="stat-content">
              <span className="stat-value">{stats.users.verified}</span>
              <span className="stat-label">Verificati</span>
            </div>
          </div>
          <div className="stat-card architect">
            <div className="stat-icon">🏛️</div>
            <div className="stat-content">
              <span className="stat-value">{stats.users.architects}</span>
              <span className="stat-label">Architetti</span>
            </div>
          </div>
          <div className="stat-card citizen">
            <div className="stat-icon">🏠</div>
            <div className="stat-content">
              <span className="stat-value">{stats.users.citizens}</span>
              <span className="stat-label">Cittadini</span>
            </div>
          </div>
        </div>
      </div>

      <div className="stats-section">
        <h2>🏛️ Architetti</h2>
        <div className="stats-grid">
          <div className="stat-card large architect">
            <div className="stat-icon">🏛️</div>
            <div className="stat-content">
              <span className="stat-value">{stats.architects.total}</span>
              <span className="stat-label">Profili Totali</span>
            </div>
          </div>
          <div className="stat-card success">
            <div className="stat-icon">👁️</div>
            <div className="stat-content">
              <span className="stat-value">{stats.architects.visible}</span>
              <span className="stat-label">Visibili</span>
            </div>
          </div>
          <div className="stat-card info">
            <div className="stat-icon">💬</div>
            <div className="stat-content">
              <span className="stat-value">{stats.architects.acceptingMessages}</span>
              <span className="stat-label">Accettano Messaggi</span>
            </div>
          </div>
          <div className="stat-card primary">
            <div className="stat-icon">🎓</div>
            <div className="stat-content">
              <span className="stat-value">{stats.architects.totalCFP}</span>
              <span className="stat-label">CFP Totali</span>
            </div>
          </div>
          <div className="stat-card success">
            <div className="stat-icon">📁</div>
            <div className="stat-content">
              <span className="stat-value">{stats.architects.totalProjects}</span>
              <span className="stat-label">Progetti Completati</span>
            </div>
          </div>
        </div>
      </div>

      <div className="stats-section">
        <h2>🎫 Token Attivazione</h2>
        <div className="stats-grid">
          <div className="stat-card large token">
            <div className="stat-icon">🎫</div>
            <div className="stat-content">
              <span className="stat-value">{stats.tokens.total}</span>
              <span className="stat-label">Token Totali</span>
            </div>
          </div>
          <div className="stat-card success">
            <div className="stat-icon">✅</div>
            <div className="stat-content">
              <span className="stat-value">{stats.tokens.used}</span>
              <span className="stat-label">Utilizzati</span>
            </div>
          </div>
          <div className="stat-card info">
            <div className="stat-icon">🎟️</div>
            <div className="stat-content">
              <span className="stat-value">{stats.tokens.available}</span>
              <span className="stat-label">Disponibili</span>
            </div>
          </div>
          <div className="stat-card warning">
            <div className="stat-icon">⏰</div>
            <div className="stat-content">
              <span className="stat-value">{stats.tokens.expired}</span>
              <span className="stat-label">Scaduti</span>
            </div>
          </div>
        </div>
      </div>

      <div className="stats-section">
        <h2>📰 News</h2>
        <div className="stats-grid">
          <div className="stat-card large news">
            <div className="stat-icon">📰</div>
            <div className="stat-content">
              <span className="stat-value">{stats.news.total}</span>
              <span className="stat-label">News Totali</span>
            </div>
          </div>
          <div className="stat-card success">
            <div className="stat-icon">✅</div>
            <div className="stat-content">
              <span className="stat-value">{stats.news.published}</span>
              <span className="stat-label">Pubblicate</span>
            </div>
          </div>
          <div className="stat-card warning">
            <div className="stat-icon">📝</div>
            <div className="stat-content">
              <span className="stat-value">{stats.news.draft}</span>
              <span className="stat-label">Bozze</span>
            </div>
          </div>
          <div className="stat-card important">
            <div className="stat-icon">⭐</div>
            <div className="stat-content">
              <span className="stat-value">{stats.news.important}</span>
              <span className="stat-label">Importanti</span>
            </div>
          </div>
        </div>
      </div>

      <div className="stats-section">
        <h2>📚 Corsi CFP</h2>
        <div className="stats-grid">
          <div className="stat-card large course">
            <div className="stat-icon">📚</div>
            <div className="stat-content">
              <span className="stat-value">{stats.courses.total}</span>
              <span className="stat-label">Corsi Totali</span>
            </div>
          </div>
          <div className="stat-card info">
            <div className="stat-icon">📅</div>
            <div className="stat-content">
              <span className="stat-value">{stats.courses.scheduled}</span>
              <span className="stat-label">Programmati</span>
            </div>
          </div>
          <div className="stat-card success">
            <div className="stat-icon">✅</div>
            <div className="stat-content">
              <span className="stat-value">{stats.courses.completed}</span>
              <span className="stat-label">Completati</span>
            </div>
          </div>
          <div className="stat-card primary">
            <div className="stat-icon">🎓</div>
            <div className="stat-content">
              <span className="stat-value">{stats.courses.totalCFP}</span>
              <span className="stat-label">CFP Offerti</span>
            </div>
          </div>
          <div className="stat-card seats">
            <div className="stat-icon">👥</div>
            <div className="stat-content">
              <span className="stat-value">{stats.courses.availableSeats}/{stats.courses.totalSeats}</span>
              <span className="stat-label">Posti Disponibili</span>
            </div>
          </div>
        </div>
      </div>

      <div className="stats-section">
        <h2>📈 Iscrizioni Mensili</h2>
        <div className="monthly-chart">
          {Object.entries(stats.monthlyRegistrations).length === 0 ? (
            <p className="no-data">Nessuna iscrizione negli ultimi 6 mesi</p>
          ) : (
            <div className="chart-bars">
              {Object.entries(stats.monthlyRegistrations).map(([month, count]) => (
                <div key={month} className="chart-bar-container">
                  <div 
                    className="chart-bar" 
                    style={{ height: `{(count / Math.max(...Object.values(stats.monthlyRegistrations))) * 200}px` }}
                  >
                    <span className="bar-value">{count}</span>
                  </div>
                  <span className="bar-label">{month}</span>
                </div>
              ))}
            </div>
          )}
        </div>
      </div>
    </div>
  );
};

export default AdminStatistics;
